export const GUIDED: Record<string, GuidedLab> = {"labex-go-atomic-counters-in-concurrent-go":{"intro":"This lab focuses on managing state in Go using the sync/atomic package for atomic counters accessed by multiple goroutines.","steps":[{"title":"Atomic Counters","body":["The problem is to increment a counter exactly 1000 times using 50 goroutines and the sync/atomic package.","• Use the sync/atomic package to increment the counter. • Use a WaitGroup to wait for all goroutines to finish their work."],"code":[{"lang":"sh","text":"# We expect to get exactly 50,000 operations. Had we\n# used the non-atomic `ops++` to increment the counter,\n# we'd likely get a different number, changing between\n# runs, because the goroutines would interfere with\n# each other. Moreover, we'd get data race failures\n# when running with the `-race` flag.\n$ go run atomic-counters.go\nops: 50000\n\n# Next we'll look at mutexes, another tool for managing\n# state."},{"lang":"go","text":"// The primary mechanism for managing state in Go is\n// communication over channels. We saw this for example\n// with [worker pools](worker-pools). There are a few other\n// options for managing state though. Here we'll\n// look at using the `sync/atomic` package for _atomic\n// counters_ accessed by multiple goroutines.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"sync\"\n\t\"sync/atomic\"\n)\n\nfunc main() {\n\n\t// We'll use an unsigned integer to represent our\n\t// (always-positive) counter.\n\tvar ops uint64\n\n\t// A WaitGroup will help us wait for all goroutines\n\t// to finish their work.\n\tvar wg sync.WaitGroup\n\n\t// We'll start 50 goroutines that each increment the\n\t// counter exactly 1000 times.\n\tfor i := 0; i < 50; i++ {\n\t\twg.Add(1)\n\n\t\tgo func() {\n\t\t\tfor c := 0; c < 1000; c++ {\n\t\t\t\t// To atomically increment the counter we\n\t\t\t\t// use `AddUint64`, giving it the memory\n\t\t\t\t// address of our `ops` counter with the\n\t\t\t\t// `&` syntax.\n\t\t\t\tatomic.AddUint64(&ops, 1)\n\t\t\t}\n\t\t\twg.Done()\n\t\t}()\n\t}\n\n\t// Wait until all the goroutines are done.\n\twg.Wait()\n\n\t// It's safe to access `ops` now because we know\n\t// no other goroutine is writing to it. Reading\n\t// atomics safely while they are being updated is"}]}],"commands":["go run atomic-counters.go"],"reference":[{"path":"atomic-counters.go","text":"// The primary mechanism for managing state in Go is\n// communication over channels. We saw this for example\n// with [worker pools](worker-pools). There are a few other\n// options for managing state though. Here we'll\n// look at using the `sync/atomic` package for _atomic\n// counters_ accessed by multiple goroutines.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"sync\"\n\t\"sync/atomic\"\n)\n\nfunc main() {\n    // TODO\n\t// We'll use an unsigned integer to represent our\n\t// (always-positive) counter.\n\t// A WaitGroup will help us wait for all goroutines\n\t// to finish their work.\n\t// We'll start 50 goroutines that each increment the\n\t// counter exactly 1000 times.\n\t// To atomically increment the counter we\n\t// use `AddUint64`, giving it the memory\n\t// address of our `ops` counter with the\n\t// `&` syntax.\n\t// Wait until all the goroutines are done.\n\t// It's safe to access `ops` now because we know\n\t// no other goroutine is writing to it. Reading\n\t// atomics safely while they are being updated is\n\t// also possible, using functions like\n\t// `atomic.LoadUint64`.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-base64-encoding-in-golang":{"intro":"This lab aims to test your knowledge of base64 encoding in Golang.","steps":[{"title":"Base64 Encoding","body":["You are required to write a Golang program that encodes and decodes a given string using both standard and URL-compatible base64 encoding.","• The program should import the encoding/base64 package with the b64 name instead of the default base64. • The program should encode the given string using both standard and URL-compatible base64 encoding. • The program should decode the encoded string using both standard and URL-compatible base64 decoding. • The program should print the encoded and decoded strings to the console."],"code":[{"lang":"sh","text":"# The string encodes to slightly different values with the\n# standard and URL base64 encoders (trailing `+` vs `-`)\n# but they both decode to the original string as desired."},{"lang":"go","text":"// Go provides built-in support for [base64\n// encoding/decoding](https://en.wikipedia.org/wiki/Base64).\n\npackage main\n\n// This syntax imports the `encoding/base64` package with\n// the `b64` name instead of the default `base64`. It'll\n// save us some space below.\nimport (\n\tb64 \"encoding/base64\"\n\t\"fmt\"\n)\n\nfunc main() {\n\n\t// Here's the `string` we'll encode/decode.\n\tdata := \"abc123!?$*&()'-=@~\"\n\n\t// Go supports both standard and URL-compatible\n\t// base64. Here's how to encode using the standard\n\t// encoder. The encoder requires a `[]byte` so we\n\t// convert our `string` to that type.\n\tsEnc := b64.StdEncoding.EncodeToString([]byte(data))\n\tfmt.Println(sEnc)\n\n\t// Decoding may return an error, which you can check\n\t// if you don't already know the input to be\n\t// well-formed.\n\tsDec, _ := b64.StdEncoding.DecodeString(sEnc)\n\tfmt.Println(string(sDec))\n\tfmt.Println()\n\n\t// This encodes/decodes using a URL-compatible base64\n\t// format.\n\tuEnc := b64.URLEncoding.EncodeToString([]byte(data))\n\tfmt.Println(uEnc)\n\tuDec, _ := b64.URLEncoding.DecodeString(uEnc)\n\tfmt.Println(string(uDec))\n}"}]}],"commands":[],"reference":[{"path":"base64-encoding.go","text":"// Go provides built-in support for [base64\n// encoding/decoding](https://en.wikipedia.org/wiki/Base64).\n\npackage main\n\n// This syntax imports the `encoding/base64` package with\n// the `b64` name instead of the default `base64`. It'll\n// save us some space below.\nimport (\n\tb64 \"encoding/base64\"\n\t\"fmt\"\n)\n\nfunc main() {\n    // TODO\n\t// Here's the `string` we'll encode/decode.\n\t// Go supports both standard and URL-compatible\n\t// base64. Here's how to encode using the standard\n\t// encoder. The encoder requires a `[]byte` so we\n\t// convert our `string` to that type.\n\t// Decoding may return an error, which you can check\n\t// if you don't already know the input to be\n\t// well-formed.\n\t// This encodes/decodes using a URL-compatible base64\n\t// format.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-buffered-channels-in-go-programming":{"intro":"This lab aims to test your understanding of buffered channels in Golang.","steps":[{"title":"Channel Buffering","body":["By default, channels in Golang are unbuffered, meaning that they only accept sends if there is a corresponding receive ready to receive the sent value. However, buffered channels accept a limited number of values without a corresponding receiver for those values. In this lab, you are required to create a buffered channel and send values into the channel without a corresponding concurrent receive.","• Basic knowledge of Golang channels • Understanding of buffered channels"],"code":[{"lang":"sh","text":"$ go run channel-buffering.go\nbuffered\nchannel"},{"lang":"go","text":"// By default channels are _unbuffered_, meaning that they\n// will only accept sends (`chan <-`) if there is a\n// corresponding receive (`<- chan`) ready to receive the\n// sent value. _Buffered channels_ accept a limited\n// number of  values without a corresponding receiver for\n// those values.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Here we `make` a channel of strings buffering up to\n\t// 2 values.\n\tmessages := make(chan string, 2)\n\n\t// Because this channel is buffered, we can send these\n\t// values into the channel without a corresponding\n\t// concurrent receive.\n\tmessages <- \"buffered\"\n\tmessages <- \"channel\"\n\n\t// Later we can receive these two values as usual.\n\tfmt.Println(<-messages)\n\tfmt.Println(<-messages)\n}"}]}],"commands":["go run channel-buffering.go"],"reference":[{"path":"channel-buffering.go","text":"// By default channels are _unbuffered_, meaning that they\n// will only accept sends (`chan <-`) if there is a\n// corresponding receive (`<- chan`) ready to receive the\n// sent value. _Buffered channels_ accept a limited\n// number of  values without a corresponding receiver for\n// those values.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    // TODO\n\t// Here we `make` a channel of strings buffering up to\n\t// 2 values.\n\t// Because this channel is buffered, we can send these\n\t// values into the channel without a corresponding\n\t// concurrent receive.\n\t// Later we can receive these two values as usual.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-synchronizing-goroutines-with-channels":{"intro":"This lab aims to test your knowledge of using channels to synchronize execution across goroutines.","steps":[{"title":"Channel Synchronization","body":["The problem to be solved in this lab is to create a goroutine that performs some work and notifies another goroutine when it's done using a channel.","To complete this lab, you will need to:","• Create a function named worker that takes a channel of type bool as a parameter. • Inside the worker function, perform some work and then send a value to the channel to notify that the work is done. • In the main function, create a channel of type bool with a buffer size of 1. • Start a goroutine that calls the worker function and passes the channel as a parameter. • Block the main function until a value is received from the channel."],"code":[{"lang":"sh","text":"$ go run channel-synchronization.go\nworking...done\n\n# If you removed the `<- done` line from this program, the\n# program would exit before the `worker` even\n# started."},{"lang":"go","text":"// We can use channels to synchronize execution\n// across goroutines. Here's an example of using a\n// blocking receive to wait for a goroutine to finish.\n// When waiting for multiple goroutines to finish,\n// you may prefer to use a [WaitGroup](waitgroups).\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\n// This is the function we'll run in a goroutine. The\n// `done` channel will be used to notify another\n// goroutine that this function's work is done.\nfunc worker(done chan bool) {\n\tfmt.Print(\"working...\")\n\ttime.Sleep(time.Second)\n\tfmt.Println(\"done\")\n\n\t// Send a value to notify that we're done.\n\tdone <- true\n}\n\nfunc main() {\n\n\t// Start a worker goroutine, giving it the channel to\n\t// notify on.\n\tdone := make(chan bool, 1)\n\tgo worker(done)\n\n\t// Block until we receive a notification from the\n\t// worker on the channel.\n\t<-done\n}"}]}],"commands":["go run channel-synchronization.go"],"reference":[{"path":"channel-synchronization.go","text":"// We can use channels to synchronize execution\n// across goroutines. Here's an example of using a\n// blocking receive to wait for a goroutine to finish.\n// When waiting for multiple goroutines to finish,\n// you may prefer to use a [WaitGroup](waitgroups).\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\n// This is the function we'll run in a goroutine. The\n// `done` channel will be used to notify another\n// goroutine that this function's work is done.\nfunc main() {\n    // TODO\n\t// Send a value to notify that we're done.\n\t// Start a worker goroutine, giving it the channel to\n\t// notify on.\n\t// Block until we receive a notification from the\n\t// worker on the channel.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-channels-concurrency":{"intro":"The Channels lab is designed to test your understanding of channels in Golang. Channels are used to connect concurrent goroutines, allowing values to be sent and received between them.","steps":[{"title":"Channels","body":["In this lab, you are required to create a new channel and send a value into it from a new goroutine. You will then receive the value from the channel and print it out.","• You must use the make(chan val-type) syntax to create a new channel. • The channel must be typed by the values it conveys. • You must use the channel <- syntax to send a value into the channel. • You must use the <-channel syntax to receive a value from the channel. • You must use a new goroutine to send the value into the channel."],"code":[{"lang":"sh","text":"# When we run the program the `\"ping\"` message is\n# successfully passed from one goroutine to another via\n# our channel.\n$ go run channels.go\nping\n\n# By default sends and receives block until both the\n# sender and receiver are ready. This property allowed\n# us to wait at the end of our program for the `\"ping\"`\n# message without having to use any other synchronization."},{"lang":"go","text":"// _Channels_ are the pipes that connect concurrent\n// goroutines. You can send values into channels from one\n// goroutine and receive those values into another\n// goroutine.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Create a new channel with `make(chan val-type)`.\n\t// Channels are typed by the values they convey.\n\tmessages := make(chan string)\n\n\t// _Send_ a value into a channel using the `channel <-`\n\t// syntax. Here we send `\"ping\"`  to the `messages`\n\t// channel we made above, from a new goroutine.\n\tgo func() { messages <- \"ping\" }()\n\n\t// The `<-channel` syntax _receives_ a value from the\n\t// channel. Here we'll receive the `\"ping\"` message\n\t// we sent above and print it out.\n\tmsg := <-messages\n\tfmt.Println(msg)\n}"}]}],"commands":["go run channels.go"],"reference":[{"path":"channels.go","text":"// _Channels_ are the pipes that connect concurrent\n// goroutines. You can send values into channels from one\n// goroutine and receive those values into another\n// goroutine.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    // TODO\n\t// Create a new channel with `make(chan val-type)`.\n\t// Channels are typed by the values they convey.\n\t// _Send_ a value into a channel using the `channel <-`\n\t// syntax. Here we send `\"ping\"`  to the `messages`\n\t// channel we made above, from a new goroutine.\n\t// The `<-channel` syntax _receives_ a value from the\n\t// channel. Here we'll receive the `\"ping\"` message\n\t// we sent above and print it out.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-command-line-flag-parsing-in-go":{"intro":"The purpose of this lab is to implement a command-line program that supports basic command-line flag parsing using the flag package in Golang.","steps":[{"title":"Command-line flags","body":["Implement a Golang program that parses command-line flags and outputs the parsed options and any trailing positional arguments. The program should support the following flags:","• word: a string flag with a default value of \"foo\". • numb: an integer flag with a default value of 42. • fork: a boolean flag with a default value of false. • svar: a string flag that uses an existing variable declared elsewhere in the program.","• The program should use the flag package to parse command-line flags. • The program should output the parsed options and any trailing positional arguments. • The program should support the word, numb, fork, and svar flags as described above."],"code":[{"lang":"sh","text":"# To experiment with the command-line flags program it's\n# best to first compile it and then run the resulting\n# binary directly.\n$ go build command-line-flags.go\n\n# Try out the built program by first giving it values for\n# all flags.\n$ ./command-line-flags -word=opt -numb=7 -fork -svar=flag\nword: opt\nnumb: 7\nfork: true\nsvar: flag\ntail: []\n\n# Note that if you omit flags they automatically take\n# their default values.\n$ ./command-line-flags -word=opt\nword: opt\nnumb: 42\nfork: false\nsvar: bar\ntail: []\n\n# Trailing positional arguments can be provided after\n# any flags.\n$ ./command-line-flags -word=opt a1 a2 a3\nword: opt\n...\ntail: [a1 a2 a3]\n\n# Note that the `flag` package requires all flags to\n# appear before positional arguments (otherwise the flags\n# will be interpreted as positional arguments).\n$ ./command-line-flags -word=opt a1 a2 a3 -numb=7\nword: opt\nnumb: 42\nfork: false\nsvar: bar\ntail: [a1 a2 a3 -numb=7]\n\n# Use `-h` or `--help` flags to get automatically\n# generated help text for the command-line program.\n$ ./command-line-flags -h\nUsage of ./command-line-flags:\n-fork=false: a bool\n-numb=42: an int\n-svar=\"bar\": a string var\n-word=\"foo\": a string"},{"lang":"go","text":"// [_Command-line flags_](https://en.wikipedia.org/wiki/Command-line_interface#Command-line_option)\n// are a common way to specify options for command-line\n// programs. For example, in `wc -l` the `-l` is a\n// command-line flag.\n\npackage main\n\n// Go provides a `flag` package supporting basic\n// command-line flag parsing. We'll use this package to\n// implement our example command-line program.\nimport (\n\t\"flag\"\n\t\"fmt\"\n)\n\nfunc main() {\n\n\t// Basic flag declarations are available for string,\n\t// integer, and boolean options. Here we declare a\n\t// string flag `word` with a default value `\"foo\"`\n\t// and a short description. This `flag.String` function\n\t// returns a string pointer (not a string value);\n\t// we'll see how to use this pointer below.\n\twordPtr := flag.String(\"word\", \"foo\", \"a string\")\n\n\t// This declares `numb` and `fork` flags, using a\n\t// similar approach to the `word` flag.\n\tnumbPtr := flag.Int(\"numb\", 42, \"an int\")\n\tforkPtr := flag.Bool(\"fork\", false, \"a bool\")\n\n\t// It's also possible to declare an option that uses an\n\t// existing var declared elsewhere in the program.\n\t// Note that we need to pass in a pointer to the flag\n\t// declaration function.\n\tvar svar string\n\tflag.StringVar(&svar, \"svar\", \"bar\", \"a string var\")\n\n\t// Once all flags are declared, call `flag.Parse()`\n\t// to execute the command-line parsing.\n\tflag.Parse()\n\n\t// Here we'll just dump out the parsed options and\n\t// any trailing positional arguments. Note that we\n\t// need to dereference the pointers with e.g. `*wordPtr`\n\t// to get the actual option values.\n\tfmt.Println(\"word:\", *wordPtr)\n\tfmt.Println(\"numb:\", *numbPtr)\n\tfmt.Println(\"fork:\", *forkPtr)"}]}],"commands":["go build command-line-flags.go"],"reference":[{"path":"command-line-flags.go","text":"// [_Command-line flags_](https://en.wikipedia.org/wiki/Command-line_interface#Command-line_option)\n// are a common way to specify options for command-line\n// programs. For example, in `wc -l` the `-l` is a\n// command-line flag.\n\npackage main\n\n// Go provides a `flag` package supporting basic\n// command-line flag parsing. We'll use this package to\n// implement our example command-line program.\nimport (\n\t\"flag\"\n\t\"fmt\"\n)\n\nfunc main() {\n    // TODO\n\t// Basic flag declarations are available for string,\n\t// integer, and boolean options. Here we declare a\n\t// string flag `word` with a default value `\"foo\"`\n\t// and a short description. This `flag.String` function\n\t// returns a string pointer (not a string value);\n\t// we'll see how to use this pointer below.\n\t// This declares `numb` and `fork` flags, using a\n\t// similar approach to the `word` flag.\n\t// It's also possible to declare an option that uses an\n\t// existing var declared elsewhere in the program.\n\t// Note that we need to pass in a pointer to the flag\n\t// declaration function.\n\t// Once all flags are declared, call `flag.Parse()`\n\t// to execute the command-line parsing.\n\t// Here we'll just dump out the parsed options and\n\t// any trailing positional arguments. Note that we\n\t// need to dereference the pointers with e.g. `*wordPtr`\n\t// to get the actual option values.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-constants-comprehension":{"intro":"This lab aims to test your understanding of constants in Golang.","steps":[{"title":"Constants","body":["The problem to be solved is to demonstrate the use of constants in Golang for character, string, boolean, and numeric values.","The lab has the following requirements:","• Use the const keyword to declare a constant value. • Constants should be of character, string, boolean, and numeric values. • A constant statement can appear anywhere a var statement can. • Demonstrate that constant expressions perform arithmetic with arbitrary precision. • A numeric constant has no type until it's given one, such as by an explicit conversion. • A number can be given a type by using it in a context that requires one, such as a variable assignment or function call."],"code":[{"lang":"sh","text":"$ go run constant.go\nconstant\n6e+11\n600000000000\n-0.28470407323754404"},{"lang":"go","text":"// Go supports _constants_ of character, string, boolean,\n// and numeric values.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math\"\n)\n\n// `const` declares a constant value.\nconst s string = \"constant\"\n\nfunc main() {\n\tfmt.Println(s)\n\n\t// A `const` statement can appear anywhere a `var`\n\t// statement can.\n\tconst n = 500000000\n\n\t// Constant expressions perform arithmetic with\n\t// arbitrary precision.\n\tconst d = 3e20 / n\n\tfmt.Println(d)\n\n\t// A numeric constant has no type until it's given\n\t// one, such as by an explicit conversion.\n\tfmt.Println(int64(d))\n\n\t// A number can be given a type by using it in a\n\t// context that requires one, such as a variable\n\t// assignment or function call. For example, here\n\t// `math.Sin` expects a `float64`.\n\tfmt.Println(math.Sin(n))\n}"}]}],"commands":["go run constant.go"],"reference":[{"path":"constants.go","text":"// Go supports _constants_ of character, string, boolean,\n// and numeric values.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math\"\n)\n\n// `const` declares a constant value.\nconst s string = \"constant\"\n\nfunc main() {\n    // TODO\n\t// A `const` statement can appear anywhere a `var`\n\t// statement can.\n\t// Constant expressions perform arithmetic with\n\t// arbitrary precision.\n\t// A numeric constant has no type until it's given\n\t// one, such as by an explicit conversion.\n\t// A number can be given a type by using it in a\n\t// context that requires one, such as a variable\n\t// assignment or function call. For example, here\n\t// `math.Sin` expects a `float64`.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-deferred-function-execution-in-go":{"intro":"The defer statement is used to delay the execution of a function until the surrounding function returns. It is often used to ensure that some cleanup is performed after a function completes, regardless of the path taken to get there.","steps":[{"title":"Defer","body":["In this lab, you need to use defer to create a file, write to it, and then close it when you're done.","• The createFile function should create a file with the given path and return a pointer to the file. • The writeFile function should write the string \"data\" to the file. • The closeFile function should close the file and check for errors."],"code":[{"lang":"sh","text":"# Running the program confirms that the file is closed\n# after being written.\n$ go run defer.go\ncreating\nwriting\nclosing"},{"lang":"go","text":"// _Defer_ is used to ensure that a function call is\n// performed later in a program's execution, usually for\n// purposes of cleanup. `defer` is often used where e.g.\n// `ensure` and `finally` would be used in other languages.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\n// Suppose we wanted to create a file, write to it,\n// and then close when we're done. Here's how we could\n// do that with `defer`.\nfunc main() {\n\n\t// Immediately after getting a file object with\n\t// `createFile`, we defer the closing of that file\n\t// with `closeFile`. This will be executed at the end\n\t// of the enclosing function (`main`), after\n\t// `writeFile` has finished.\n\tf := createFile(\"/tmp/defer.txt\")\n\tdefer closeFile(f)\n\twriteFile(f)\n}\n\nfunc createFile(p string) *os.File {\n\tfmt.Println(\"creating\")\n\tf, err := os.Create(p)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn f\n}\n\nfunc writeFile(f *os.File) {\n\tfmt.Println(\"writing\")\n\tfmt.Fprintln(f, \"data\")\n\n}\n\nfunc closeFile(f *os.File) {\n\tfmt.Println(\"closing\")\n\terr := f.Close()\n\t// It's important to check for errors when closing a\n\t// file, even in a deferred function.\n\tif err != nil {"}]}],"commands":["go run defer.go"],"reference":[{"path":"defer.go","text":"// _Defer_ is used to ensure that a function call is\n// performed later in a program's execution, usually for\n// purposes of cleanup. `defer` is often used where e.g.\n// `ensure` and `finally` would be used in other languages.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\n// Suppose we wanted to create a file, write to it,\n// and then close when we're done. Here's how we could\n// do that with `defer`.\nfunc main() {\n    // TODO\n\t// Immediately after getting a file object with\n\t// `createFile`, we defer the closing of that file\n\t// with `closeFile`. This will be executed at the end\n\t// of the enclosing function (`main`), after\n\t// `writeFile` has finished.\n\t// It's important to check for errors when closing a\n\t// file, even in a deferred function.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-embedding-files-in-go-binaries":{"intro":"This lab aims to test your understanding of the embed package in Golang. The embed package allows programs to include arbitrary files and folders in the Go binary at build time.","steps":[{"title":"Embed Directive","body":["Your task is to modify the given code to embed files and folders into the Go binary and print their contents.","• You must use the embed package to embed files and folders. • You must use the string and []byte types to store the contents of the embedded files. • You must use the embed.FS type to embed multiple files or folders with wildcards. • You must print the contents of the embedded files."],"code":[{"lang":"sh","text":"# Use these commands to run the example.\n# (Note: due to limitation on go playground,\n# this example can only be run on your local machine.)\n$ mkdir -p folder\n$ echo \"hello go\" > folder/single_file.txt\n$ echo \"123\" > folder/file1.hash\n$ echo \"456\" > folder/file2.hash\n\n$ go run embed-directive.go\nhello go\nhello go\n123\n456"},{"lang":"go","text":"// `//go:embed` is a [compiler\n// directive](https://pkg.go.dev/cmd/compile#hdr-Compiler_Directives) that\n// allows programs to include arbitrary files and folders in the Go binary at\n// build time. Read more about the embed directive\n// [here](https://pkg.go.dev/embed).\npackage main\n\n// Import the `embed` package; if you don't use any exported\n// identifiers from this package, you can do a blank import with `_ \"embed\"`.\nimport (\n\t\"embed\"\n)\n\n// `embed` directives accept paths relative to the directory containing the\n// Go source file. This directive embeds the contents of the file into the\n// `string` variable immediately following it.\n//\n//go:embed folder/single_file.txt\nvar fileString string\n\n// Or embed the contents of the file into a `[]byte`.\n//\n//go:embed folder/single_file.txt\nvar fileByte []byte\n\n// We can also embed multiple files or even folders with wildcards. This uses\n// a variable of the [embed.FS type](https://pkg.go.dev/embed#FS), which\n// implements a simple virtual file system.\n//\n//go:embed folder/single_file.txt\n//go:embed folder/*.hash\nvar folder embed.FS\n\nfunc main() {\n\n\t// Print out the contents of `single_file.txt`.\n\tprint(fileString)\n\tprint(string(fileByte))\n\n\t// Retrieve some files from the embedded folder.\n\tcontent1, _ := folder.ReadFile(\"folder/file1.hash\")\n\tprint(string(content1))\n\n\tcontent2, _ := folder.ReadFile(\"folder/file2.hash\")\n\tprint(string(content2))\n}"}]}],"commands":["mkdir -p folder","echo \"hello go\" > folder/single_file.txt","echo \"123\" > folder/file1.hash","echo \"456\" > folder/file2.hash","go run embed-directive.go"],"reference":[{"path":"embed-directive.go","text":"// `//go:embed` is a [compiler\n// directive](https://pkg.go.dev/cmd/compile#hdr-Compiler_Directives) that\n// allows programs to include arbitrary files and folders in the Go binary at\n// build time. Read more about the embed directive\n// [here](https://pkg.go.dev/embed).\npackage main\n\n// Import the `embed` package; if you don't use any exported\n// identifiers from this package, you can do a blank import with `_ \"embed\"`.\nimport (\n\t\"embed\"\n)\n\n// `embed` directives accept paths relative to the directory containing the\n// Go source file. This directive embeds the contents of the file into the\n// `string` variable immediately following it.\n//\n//go:embed folder/single_file.txt\nvar fileString string\n\n// Or embed the contents of the file into a `[]byte`.\n//\n//go:embed folder/single_file.txt\nvar fileByte []byte\n\n// We can also embed multiple files or even folders with wildcards. This uses\n// a variable of the [embed.FS type](https://pkg.go.dev/embed#FS), which\n// implements a simple virtual file system.\n//\n//go:embed folder/single_file.txt\n//go:embed folder/*.hash\nvar folder embed.FS\n\nfunc main() {\n    // TODO\n\t// Print out the contents of `single_file.txt`.\n\t// Retrieve some files from the embedded folder.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-fundamentals-of-unix-environment-variables":{"intro":"This lab will cover the basics of environment variables in Unix programs. Environment variables are used to convey configuration information to programs.","steps":[{"title":"Environment Variables","body":[],"code":[{"lang":"sh","text":"# Running the program shows that we pick up the value\n# for `FOO` that we set in the program, but that\n# `BAR` is empty.\n$ go run environment-variables.go\nFOO: 1\nBAR:\n\n# The list of keys in the environment will depend on your\n# particular machine.\nTERM_PROGRAM\nPATH\nSHELL\n...\nFOO\n\n# If we set `BAR` in the environment first, the running\n# program picks that value up.\n$ BAR=2 go run environment-variables.go\nFOO: 1\nBAR: 2\n..."},{"lang":"go","text":"// [Environment variables](https://en.wikipedia.org/wiki/Environment_variable)\n// are a universal mechanism for [conveying configuration\n// information to Unix programs](https://www.12factor.net/config).\n// Let's look at how to set, get, and list environment variables.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"strings\"\n)\n\nfunc main() {\n\n\t// To set a key/value pair, use `os.Setenv`. To get a\n\t// value for a key, use `os.Getenv`. This will return\n\t// an empty string if the key isn't present in the\n\t// environment.\n\tos.Setenv(\"FOO\", \"1\")\n\tfmt.Println(\"FOO:\", os.Getenv(\"FOO\"))\n\tfmt.Println(\"BAR:\", os.Getenv(\"BAR\"))\n\n\t// Use `os.Environ` to list all key/value pairs in the\n\t// environment. This returns a slice of strings in the\n\t// form `KEY=value`. You can `strings.SplitN` them to\n\t// get the key and value. Here we print all the keys.\n\tfmt.Println()\n\tfor _, e := range os.Environ() {\n\t\tpair := strings.SplitN(e, \"=\", 2)\n\t\tfmt.Println(pair[0])\n\t}\n}"}]}],"commands":["go run environment-variables.go"],"reference":[{"path":"environment-variables.go","text":"// [Environment variables](https://en.wikipedia.org/wiki/Environment_variable)\n// are a universal mechanism for [conveying configuration\n// information to Unix programs](https://www.12factor.net/config).\n// Let's look at how to set, get, and list environment variables.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"strings\"\n)\n\nfunc main() {\n    // TODO\n\t// To set a key/value pair, use `os.Setenv`. To get a\n\t// value for a key, use `os.Getenv`. This will return\n\t// an empty string if the key isn't present in the\n\t// environment.\n\t// Use `os.Environ` to list all key/value pairs in the\n\t// environment. This returns a slice of strings in the\n\t// form `KEY=value`. You can `strings.SplitN` them to\n\t// get the key and value. Here we print all the keys.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-unix-epoch-time-retrieval":{"intro":"The Epoch lab is a Golang lab that aims to test your ability to get the number of seconds, milliseconds, or nanoseconds since the Unix epoch.","steps":[{"title":"Epoch","body":["The problem to be solved in this lab is to write a Golang program that can calculate the number of seconds, milliseconds, or nanoseconds since the Unix epoch.","To complete this lab, you need to have a basic understanding of Golang and the following requirements:","• Familiarity with the time package in Golang. • Knowledge of how to use the Unix, UnixMilli, and UnixNano functions in the time package."],"code":[{"lang":"sh","text":"$ go run epoch.go\n2012-10-31 16:13:58.292387 +0000 UTC\n1351700038\n1351700038292\n1351700038292387000\n2012-10-31 16:13:58 +0000 UTC\n2012-10-31 16:13:58.292387 +0000 UTC\n\n# Next we'll look at another time-related task: time\n# parsing and formatting."},{"lang":"go","text":"// A common requirement in programs is getting the number\n// of seconds, milliseconds, or nanoseconds since the\n// [Unix epoch](https://en.wikipedia.org/wiki/Unix_time).\n// Here's how to do it in Go.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n\n\t// Use `time.Now` with `Unix`, `UnixMilli` or `UnixNano`\n\t// to get elapsed time since the Unix epoch in seconds,\n\t// milliseconds or nanoseconds, respectively.\n\tnow := time.Now()\n\tfmt.Println(now)\n\n\tfmt.Println(now.Unix())\n\tfmt.Println(now.UnixMilli())\n\tfmt.Println(now.UnixNano())\n\n\t// You can also convert integer seconds or nanoseconds\n\t// since the epoch into the corresponding `time`.\n\tfmt.Println(time.Unix(now.Unix(), 0))\n\tfmt.Println(time.Unix(0, now.UnixNano()))\n}"}]}],"commands":["go run epoch.go"],"reference":[{"path":"epoch.go","text":"// A common requirement in programs is getting the number\n// of seconds, milliseconds, or nanoseconds since the\n// [Unix epoch](https://en.wikipedia.org/wiki/Unix_time).\n// Here's how to do it in Go.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n    // TODO\n\t// Use `time.Now` with `Unix`, `UnixMilli` or `UnixNano`\n\t// to get elapsed time since the Unix epoch in seconds,\n\t// milliseconds or nanoseconds, respectively.\n\t// You can also convert integer seconds or nanoseconds\n\t// since the epoch into the corresponding `time`.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-replacing-go-process-with-exec":{"intro":"This lab focuses on replacing the current Go process with another process using Go's implementation of the classic exec function.","steps":[{"title":"Execing Processes","body":["The problem is to replace the current Go process with another process, such as a non-Go process."],"code":[{"lang":"sh","text":"# When we run our program it is replaced by `ls`.\n$ go run execing-processes.go\ntotal 16\ndrwxr-xr-x 4 mark 136B Oct 3 16:29 .\ndrwxr-xr-x 91 mark 3.0K Oct 3 12:50 ..\n-rw-r--r-- 1 mark 1.3K Oct 3 16:28 execing-processes.go\n\n# Note that Go does not offer a classic Unix `fork`\n# function. Usually this isn't an issue though, since\n# starting goroutines, spawning processes, and exec'ing\n# processes covers most use cases for `fork`."},{"lang":"go","text":"// In the previous example we looked at\n// [spawning external processes](spawning-processes). We\n// do this when we need an external process accessible to\n// a running Go process. Sometimes we just want to\n// completely replace the current Go process with another\n// (perhaps non-Go) one. To do this we'll use Go's\n// implementation of the classic\n// <a href=\"https://en.wikipedia.org/wiki/Exec_(operating_system)\"><code>exec</code></a>\n// function.\n\npackage main\n\nimport (\n\t\"os\"\n\t\"os/exec\"\n\t\"syscall\"\n)\n\nfunc main() {\n\n\t// For our example we'll exec `ls`. Go requires an\n\t// absolute path to the binary we want to execute, so\n\t// we'll use `exec.LookPath` to find it (probably\n\t// `/bin/ls`).\n\tbinary, lookErr := exec.LookPath(\"ls\")\n\tif lookErr != nil {\n\t\tpanic(lookErr)\n\t}\n\n\t// `Exec` requires arguments in slice form (as\n\t// opposed to one big string). We'll give `ls` a few\n\t// common arguments. Note that the first argument should\n\t// be the program name.\n\targs := []string{\"ls\", \"-a\", \"-l\", \"-h\"}\n\n\t// `Exec` also needs a set of [environment variables](environment-variables)\n\t// to use. Here we just provide our current\n\t// environment.\n\tenv := os.Environ()\n\n\t// Here's the actual `syscall.Exec` call. If this call is\n\t// successful, the execution of our process will end\n\t// here and be replaced by the `/bin/ls -a -l -h`\n\t// process. If there is an error we'll get a return\n\t// value.\n\texecErr := syscall.Exec(binary, args, env)\n\tif execErr != nil {\n\t\tpanic(execErr)"}]}],"commands":["go run execing-processes.go"],"reference":[{"path":"execing-processes.go","text":"// In the previous example we looked at\n// [spawning external processes](spawning-processes). We\n// do this when we need an external process accessible to\n// a running Go process. Sometimes we just want to\n// completely replace the current Go process with another\n// (perhaps non-Go) one. To do this we'll use Go's\n// implementation of the classic\n// <a href=\"https://en.wikipedia.org/wiki/Exec_(operating_system)\"><code>exec</code></a>\n// function.\n\npackage main\n\nimport (\n\t\"os\"\n\t\"os/exec\"\n\t\"syscall\"\n)\n\nfunc main() {\n    // TODO\n\t// For our example we'll exec `ls`. Go requires an\n\t// absolute path to the binary we want to execute, so\n\t// we'll use `exec.LookPath` to find it (probably\n\t// `/bin/ls`).\n\t// `Exec` requires arguments in slice form (as\n\t// opposed to one big string). We'll give `ls` a few\n\t// common arguments. Note that the first argument should\n\t// be the program name.\n\t// `Exec` also needs a set of [environment variables](environment-variables)\n\t// to use. Here we just provide our current\n\t// environment.\n\t// Here's the actual `syscall.Exec` call. If this call is\n\t// successful, the execution of our process will end\n\t// here and be replaced by the `/bin/ls -a -l -h`\n\t// process. If there is an error we'll get a return\n\t// value.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-exit-function-in-go":{"intro":"The Exit lab is designed to test your ability to use the os.Exit function in Go to immediately exit with a given status.","steps":[{"title":"Exit","body":["The problem to be solved in this lab is to exit a Go program with a specific status code using the os.Exit function.","To complete this lab, you will need to have a basic understanding of Go programming and the os package."],"code":[{"lang":"sh","text":"#  If you run `exit.go` using `go run`, the exit\n# will be picked up by `go` and printed.\n$ go run exit.go\nexit status 3\n\n# By building and executing a binary you can see\n# the status in the terminal.\n$ go build exit.go\n$ ./exit\n$ echo $?\n3\n\n# Note that the `!` from our program never got printed."},{"lang":"go","text":"// Use `os.Exit` to immediately exit with a given\n// status.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\nfunc main() {\n\n\t// `defer`s will _not_ be run when using `os.Exit`, so\n\t// this `fmt.Println` will never be called.\n\tdefer fmt.Println(\"!\")\n\n\t// Exit with status 3.\n\tos.Exit(3)\n}\n\n// Note that unlike e.g. C, Go does not use an integer\n// return value from `main` to indicate exit status. If\n// you'd like to exit with a non-zero status you should\n// use `os.Exit`."}]}],"commands":["go run exit.go","go build exit.go","echo $?"],"reference":[{"path":"exit.go","text":"// Use `os.Exit` to immediately exit with a given\n// status.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\nfunc main() {\n    // TODO\n\t// `defer`s will _not_ be run when using `os.Exit`, so\n\t// this `fmt.Println` will never be called.\n\t// Exit with status 3.\n}\n\n// Note that unlike e.g. C, Go does not use an integer\n// return value from `main` to indicate exit status. If\n// you'd like to exit with a non-zero status you should\n// use `os.Exit`."}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-for-loop-understanding":{"intro":"This lab aims to test your understanding of the for loop in Golang.","steps":[{"title":"For","body":["The code below contains different types of for loops. However, some parts of the code are incomplete, and you need to fill in the blanks to make the code work correctly.","• Basic knowledge of Golang syntax • Familiarity with for loops in Golang"],"code":[{"lang":"sh","text":"$ go run for.go\n1\n2\n3\n7\n8\n9\nloop\n1\n3\n5\n\n# We'll see some other `for` forms later when we look at\n# `range` statements, channels, and other data\n# structures."},{"lang":"go","text":"// `for` is Go's only looping construct. Here are\n// some basic types of `for` loops.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// The most basic type, with a single condition.\n\ti := 1\n\tfor i <= 3 {\n\t\tfmt.Println(i)\n\t\ti = i + 1\n\t}\n\n\t// A classic initial/condition/after `for` loop.\n\tfor j := 7; j <= 9; j++ {\n\t\tfmt.Println(j)\n\t}\n\n\t// `for` without a condition will loop repeatedly\n\t// until you `break` out of the loop or `return` from\n\t// the enclosing function.\n\tfor {\n\t\tfmt.Println(\"loop\")\n\t\tbreak\n\t}\n\n\t// You can also `continue` to the next iteration of\n\t// the loop.\n\tfor n := 0; n <= 5; n++ {\n\t\tif n%2 == 0 {\n\t\t\tcontinue\n\t\t}\n\t\tfmt.Println(n)\n\t}\n}"}]}],"commands":["go run for.go"],"reference":[{"path":"for.go","text":"// `for` is Go's only looping construct. Here are\n// some basic types of `for` loops.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    // TODO\n\t// The most basic type, with a single condition.\n\t// A classic initial/condition/after `for` loop.\n\t// `for` without a condition will loop repeatedly\n\t// until you `break` out of the loop or `return` from\n\t// the enclosing function.\n\t// You can also `continue` to the next iteration of\n\t// the loop.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-functions-in-go-programming":{"intro":"In this lab, we will learn about functions in Go. We will see how to define functions, how to pass arguments to them, and how to return values from them.","steps":[{"title":"Functions","body":["In the given code, we have two functions plus and plusPlus. The plus function takes two integers as arguments and returns their sum. The plusPlus function takes three integers as arguments and returns their sum. Your task is to complete the plusPlus function by adding the third integer to the sum of the first two integers.","• The plus function should take two integers as arguments and return their sum as an integer. • The plusPlus function should take three integers as arguments and return their sum as an integer. • The plusPlus function should use the plus function to calculate the sum of the first two integers."],"code":[{"lang":"sh","text":"$ go run functions.go\n1+2 = 3\n1+2+3 = 6\n\n# There are several other features to Go functions. One is\n# multiple return values, which we'll look at next."},{"lang":"go","text":"// _Functions_ are central in Go. We'll learn about\n// functions with a few different examples.\n\npackage main\n\nimport \"fmt\"\n\n// Here's a function that takes two `int`s and returns\n// their sum as an `int`.\nfunc plus(a int, b int) int {\n\n\t// Go requires explicit returns, i.e. it won't\n\t// automatically return the value of the last\n\t// expression.\n\treturn a + b\n}\n\n// When you have multiple consecutive parameters of\n// the same type, you may omit the type name for the\n// like-typed parameters up to the final parameter that\n// declares the type.\nfunc plusPlus(a, b, c int) int {\n\treturn a + b + c\n}\n\nfunc main() {\n\n\t// Call a function just as you'd expect, with\n\t// `name(args)`.\n\tres := plus(1, 2)\n\tfmt.Println(\"1+2 =\", res)\n\n\tres = plusPlus(1, 2, 3)\n\tfmt.Println(\"1+2+3 =\", res)\n}"}]}],"commands":["go run functions.go"],"reference":[{"path":"functions.go","text":"// _Functions_ are central in Go. We'll learn about\n// functions with a few different examples.\n\npackage main\n\nimport \"fmt\"\n\n// Here's a function that takes two `int`s and returns\n// their sum as an `int`.\nfunc main() {\n    // TODO\n\t// Go requires explicit returns, i.e. it won't\n\t// automatically return the value of the last\n\t// expression.\n\n// When you have multiple consecutive parameters of\n\n// the same type, you may omit the type name for the\n\n// like-typed parameters up to the final parameter that\n\n// declares the type.\n\t// Call a function just as you'd expect, with\n\t// `name(args)`.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-generics-in-go-1-18":{"intro":"This lab introduces the concept of generics in Golang. Starting from version 1.18, Golang has added support for generics, which allows us to write more flexible and reusable code.","steps":[{"title":"Generics","body":["The problem to be solved in this lab is to understand how to define and use generic functions and types in Golang.","• Understand the concept of generics in Golang. • Know how to define generic functions with type parameters and constraints. • Know how to define generic types with type parameters. • Understand how to define methods on generic types. • Know how to invoke generic functions with type inference."],"code":[{"lang":"sh","text":"$ go run generics.go\nkeys: [4 1 2]\nlist: [10 13 23]"},{"lang":"go","text":"// Starting with version 1.18, Go has added support for\n// _generics_, also known as _type parameters_.\n\npackage main\n\nimport \"fmt\"\n\n// As an example of a generic function, `MapKeys` takes\n// a map of any type and returns a slice of its keys.\n// This function has two type parameters - `K` and `V`;\n// `K` has the `comparable` _constraint_, meaning that\n// we can compare values of this type with the `==` and\n// `!=` operators. This is required for map keys in Go.\n// `V` has the `any` constraint, meaning that it's not\n// restricted in any way (`any` is an alias for `interface{}`).\nfunc MapKeys[K comparable, V any](m map[K]V) []K {\n\tr := make([]K, 0, len(m))\n\tfor k := range m {\n\t\tr = append(r, k)\n\t}\n\treturn r\n}\n\n// As an example of a generic type, `List` is a\n// singly-linked list with values of any type.\ntype List[T any] struct {\n\thead, tail *element[T]\n}\n\ntype element[T any] struct {\n\tnext *element[T]\n\tval  T\n}\n\n// We can define methods on generic types just like we\n// do on regular types, but we have to keep the type\n// parameters in place. The type is `List[T]`, not `List`.\nfunc (lst *List[T]) Push(v T) {\n\tif lst.tail == nil {\n\t\tlst.head = &element[T]{val: v}\n\t\tlst.tail = lst.head\n\t} else {\n\t\tlst.tail.next = &element[T]{val: v}\n\t\tlst.tail = lst.tail.next\n\t}\n}\n\nfunc (lst *List[T]) GetAll() []T {"}]}],"commands":["go run generics.go"],"reference":[{"path":"generics.go","text":"// Starting with version 1.18, Go has added support for\n// _generics_, also known as _type parameters_.\n\npackage main\n\nimport \"fmt\"\n\n// As an example of a generic function, `MapKeys` takes\n// a map of any type and returns a slice of its keys.\n// This function has two type parameters - `K` and `V`;\n// `K` has the `comparable` _constraint_, meaning that\n// we can compare values of this type with the `==` and\n// `!=` operators. This is required for map keys in Go.\n// `V` has the `any` constraint, meaning that it's not\n// restricted in any way (`any` is an alias for `interface{}`).\nfunc main() {\n    // TODO\n\n// As an example of a generic type, `List` is a\n\n// singly-linked list with values of any type.\n\n// We can define methods on generic types just like we\n\n// do on regular types, but we have to keep the type\n\n// parameters in place. The type is `List[T]`, not `List`.\n\t// When invoking generic functions, we can often rely\n\t// on _type inference_. Note that we don't have to\n\t// specify the types for `K` and `V` when\n\t// calling `MapKeys` - the compiler infers them\n\t// automatically.\n\t// ... though we could also specify them explicitly.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-goroutines-concurrency":{"intro":"This lab is designed to test your understanding of goroutines in Golang. Goroutines are lightweight threads of execution that allow for concurrent execution of functions.","steps":[{"title":"Goroutines","body":["The problem to be solved in this lab is to create and run goroutines to execute functions concurrently.","• The f function should print out its input string and a counter variable three times. • The main function should call the f function synchronously and print out \"direct\" and a counter variable three times. • The main function should call the f function asynchronously using a goroutine and print out \"goroutine\" and a counter variable three times. • The main function should start a goroutine to execute an anonymous function that prints out a message. • The main function should wait for the goroutines to finish executing before printing out \"done\"."],"code":[{"lang":"sh","text":"# When we run this program, we see the output of the\n# blocking call first, then the output of the two\n# goroutines. The goroutines' output may be interleaved,\n# because goroutines are being run concurrently by the\n# Go runtime.\n\n# Next we'll look at a complement to goroutines in\n# concurrent Go programs: channels."},{"lang":"go","text":"// A _goroutine_ is a lightweight thread of execution.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc f(from string) {\n\tfor i := 0; i < 3; i++ {\n\t\tfmt.Println(from, \":\", i)\n\t}\n}\n\nfunc main() {\n\n\t// Suppose we have a function call `f(s)`. Here's how\n\t// we'd call that in the usual way, running it\n\t// synchronously.\n\tf(\"direct\")\n\n\t// To invoke this function in a goroutine, use\n\t// `go f(s)`. This new goroutine will execute\n\t// concurrently with the calling one.\n\tgo f(\"goroutine\")\n\n\t// You can also start a goroutine for an anonymous\n\t// function call.\n\tgo func(msg string) {\n\t\tfmt.Println(msg)\n\t}(\"going\")\n\n\t// Our two function calls are running asynchronously in\n\t// separate goroutines now. Wait for them to finish\n\t// (for a more robust approach, use a [WaitGroup](waitgroups)).\n\ttime.Sleep(time.Second)\n\tfmt.Println(\"done\")\n}"}]}],"commands":[],"reference":[{"path":"goroutines.go","text":"// A _goroutine_ is a lightweight thread of execution.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n    // TODO\n\t// Suppose we have a function call `f(s)`. Here's how\n\t// we'd call that in the usual way, running it\n\t// synchronously.\n\t// To invoke this function in a goroutine, use\n\t// `go f(s)`. This new goroutine will execute\n\t// concurrently with the calling one.\n\t// You can also start a goroutine for an anonymous\n\t// function call.\n\t// Our two function calls are running asynchronously in\n\t// separate goroutines now. Wait for them to finish\n\t// (for a more robust approach, use a [WaitGroup](waitgroups)).\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-basic-http-server-in-go":{"intro":"This lab aims to test your ability to write a basic HTTP server using the net/http package in Golang.","steps":[{"title":"HTTP Server","body":["You are required to write a simple HTTP server that can handle two routes: /hello and /headers. The /hello route should return a simple \"hello\" response, while the /headers route should return all the HTTP request headers.","• The server should use the net/http package. • The /hello route should return a \"hello\" response. • The /headers route should return all the HTTP request headers. • The server should listen on port 8090."],"code":[{"lang":"sh","text":"# Run the server in the background.\n$ go run http-servers.go &\n\n# Access the `/hello` route.\n$ curl localhost:8090/hello\nhello"},{"lang":"go","text":"// Writing a basic HTTP server is easy using the\n// `net/http` package.\npackage main\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n)\n\n// A fundamental concept in `net/http` servers is\n// *handlers*. A handler is an object implementing the\n// `http.Handler` interface. A common way to write\n// a handler is by using the `http.HandlerFunc` adapter\n// on functions with the appropriate signature.\nfunc hello(w http.ResponseWriter, req *http.Request) {\n\n\t// Functions serving as handlers take a\n\t// `http.ResponseWriter` and a `http.Request` as\n\t// arguments. The response writer is used to fill in the\n\t// HTTP response. Here our simple response is just\n\t// \"hello\\n\".\n\tfmt.Fprintf(w, \"hello\\n\")\n}\n\nfunc headers(w http.ResponseWriter, req *http.Request) {\n\n\t// This handler does something a little more\n\t// sophisticated by reading all the HTTP request\n\t// headers and echoing them into the response body.\n\tfor name, headers := range req.Header {\n\t\tfor _, h := range headers {\n\t\t\tfmt.Fprintf(w, \"%v: %v\\n\", name, h)\n\t\t}\n\t}\n}\n\nfunc main() {\n\n\t// We register our handlers on server routes using the\n\t// `http.HandleFunc` convenience function. It sets up\n\t// the *default router* in the `net/http` package and\n\t// takes a function as an argument.\n\thttp.HandleFunc(\"/hello\", hello)\n\thttp.HandleFunc(\"/headers\", headers)\n\n\t// Finally, we call the `ListenAndServe` with the port\n\t// and a handler. `nil` tells it to use the default\n\t// router we've just set up."}]}],"commands":["go run http-servers.go &","curl localhost:8090/hello"],"reference":[{"path":"http-server.go","text":"// Writing a basic HTTP server is easy using the\n// `net/http` package.\npackage main\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n)\n\n// A fundamental concept in `net/http` servers is\n// *handlers*. A handler is an object implementing the\n// `http.Handler` interface. A common way to write\n// a handler is by using the `http.HandlerFunc` adapter\n// on functions with the appropriate signature.\nfunc main() {\n    // TODO\n\t// Functions serving as handlers take a\n\t// `http.ResponseWriter` and a `http.Request` as\n\t// arguments. The response writer is used to fill in the\n\t// HTTP response. Here our simple response is just\n\t// \"hello\\n\".\n\t// This handler does something a little more\n\t// sophisticated by reading all the HTTP request\n\t// headers and echoing them into the response body.\n\t// We register our handlers on server routes using the\n\t// `http.HandleFunc` convenience function. It sets up\n\t// the *default router* in the `net/http` package and\n\t// takes a function as an argument.\n\t// Finally, we call the `ListenAndServe` with the port\n\t// and a handler. `nil` tells it to use the default\n\t// router we've just set up.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-if-else-branching":{"intro":"The if-else lab in Golang is designed to test your knowledge of branching with if and else statements in Go.","steps":[{"title":"If Else","body":["You are required to complete the checkNumber function that takes an integer as input and returns a string. If the number is even, return \"even\", otherwise return \"odd\".","• The function should be named checkNumber. • The function should take an integer as input. • The function should return a string. • If the number is even, return \"even\". • If the number is odd, return \"odd\"."],"code":[{"lang":"sh","text":"$ go run if-else.go\n7 is odd\n8 is divisible by 4\n9 has 1 digit\n\n# There is no [ternary if](https://en.wikipedia.org/wiki/%3F:)\n# in Go, so you'll need to use a full `if` statement even\n# for basic conditions."},{"lang":"go","text":"// Branching with `if` and `else` in Go is\n// straight-forward.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Here's a basic example.\n\tif 7%2 == 0 {\n\t\tfmt.Println(\"7 is even\")\n\t} else {\n\t\tfmt.Println(\"7 is odd\")\n\t}\n\n\t// You can have an `if` statement without an else.\n\tif 8%4 == 0 {\n\t\tfmt.Println(\"8 is divisible by 4\")\n\t}\n\n\t// A statement can precede conditionals; any variables\n\t// declared in this statement are available in the current\n\t// and all subsequent branches.\n\tif num := 9; num < 0 {\n\t\tfmt.Println(num, \"is negative\")\n\t} else if num < 10 {\n\t\tfmt.Println(num, \"has 1 digit\")\n\t} else {\n\t\tfmt.Println(num, \"has multiple digits\")\n\t}\n}\n\n// Note that you don't need parentheses around conditions\n// in Go, but that the braces are required."}]}],"commands":["go run if-else.go"],"reference":[{"path":"if-else.go","text":"// Branching with `if` and `else` in Go is\n// straight-forward.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    // TODO\n\t// Here's a basic example.\n\t// You can have an `if` statement without an else.\n\t// A statement can precede conditionals; any variables\n\t// declared in this statement are available in the current\n\t// and all subsequent branches.\n}\n\n// Note that you don't need parentheses around conditions\n// in Go, but that the braces are required."}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-interfaces-tutorial":{"intro":"This lab is about interfaces in Golang. Interfaces are named collections of method signatures.","steps":[{"title":"Interfaces","body":["The problem is to implement an interface in Go, we just need to implement all the methods in the interface. Here we implement geometry on rects and circles.","• Implement an interface in Go. • Implement all the methods in the interface. • Use a generic measure function to work on any geometry. • Use instances of circle and rect structs as arguments to measure."],"code":[{"lang":"sh","text":"$ go run interfaces.go\n{3 4}\n12\n14\n{5}\n78.53981633974483\n31.41592653589793\n\n# To learn more about Go's interfaces, check out this\n# [great blog post](https://jordanorelli.tumblr.com/post/32665860244/how-to-use-interfaces-in-go)."},{"lang":"go","text":"// _Interfaces_ are named collections of method\n// signatures.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math\"\n)\n\n// Here's a basic interface for geometric shapes.\ntype geometry interface {\n\tarea() float64\n\tperim() float64\n}\n\n// For our example we'll implement this interface on\n// `rect` and `circle` types.\ntype rect struct {\n\twidth, height float64\n}\ntype circle struct {\n\tradius float64\n}\n\n// To implement an interface in Go, we just need to\n// implement all the methods in the interface. Here we\n// implement `geometry` on `rect`s.\nfunc (r rect) area() float64 {\n\treturn r.width * r.height\n}\nfunc (r rect) perim() float64 {\n\treturn 2*r.width + 2*r.height\n}\n\n// The implementation for `circle`s.\nfunc (c circle) area() float64 {\n\treturn math.Pi * c.radius * c.radius\n}\nfunc (c circle) perim() float64 {\n\treturn 2 * math.Pi * c.radius\n}\n\n// If a variable has an interface type, then we can call\n// methods that are in the named interface. Here's a\n// generic `measure` function taking advantage of this\n// to work on any `geometry`.\nfunc measure(g geometry) {"}]}],"commands":["go run interfaces.go"],"reference":[{"path":"interfaces.go","text":"// _Interfaces_ are named collections of method\n// signatures.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math\"\n)\n\n// Here's a basic interface for geometric shapes.\ntype geometry interface {\n\tarea() float64\n\tperim() float64\n}\n\n// For our example we'll implement this interface on\n// `rect` and `circle` types.\ntype rect struct {\n\twidth, height float64\n}\ntype circle struct {\n\tradius float64\n}\n\n// To implement an interface in Go, we just need to\n// implement all the methods in the interface. Here we\n// implement `geometry` on `rect`s.\nfunc main() {\n    // TODO\n\n// The implementation for `circle`s.\n\n// If a variable has an interface type, then we can call\n\n// methods that are in the named interface. Here's a\n\n// generic `measure` function taking advantage of this\n\n// to work on any `geometry`.\n\t// The `circle` and `rect` struct types both\n\t// implement the `geometry` interface so we can use\n\t// instances of\n\t// these structs as arguments to `measure`.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-json-encoding-and-decoding":{"intro":"This lab aims to test your knowledge of encoding and decoding JSON data in Golang.","steps":[{"title":"JSON","body":["You are required to complete the code provided to encode and decode JSON data in Golang. The code contains examples of encoding and decoding basic data types, as well as custom data types.","• Basic knowledge of Golang programming language. • Familiarity with encoding and decoding JSON data in Golang. • Ability to read and understand existing Golang code."],"code":[{"lang":"sh","text":"# We've covered the basic of JSON in Go here, but check\n# out the [JSON and Go](https://go.dev/blog/json)\n# blog post and [JSON package docs](https://pkg.go.dev/encoding/json)\n# for more."},{"lang":"go","text":"// Go offers built-in support for JSON encoding and\n// decoding, including to and from built-in and custom\n// data types.\n\npackage main\n\nimport (\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"os\"\n)\n\n// We'll use these two structs to demonstrate encoding and\n// decoding of custom types below.\ntype response1 struct {\n\tPage   int\n\tFruits []string\n}\n\n// Only exported fields will be encoded/decoded in JSON.\n// Fields must start with capital letters to be exported.\ntype response2 struct {\n\tPage   int      `json:\"page\"`\n\tFruits []string `json:\"fruits\"`\n}\n\nfunc main() {\n\n\t// First we'll look at encoding basic data types to\n\t// JSON strings. Here are some examples for atomic\n\t// values.\n\tbolB, _ := json.Marshal(true)\n\tfmt.Println(string(bolB))\n\n\tintB, _ := json.Marshal(1)\n\tfmt.Println(string(intB))\n\n\tfltB, _ := json.Marshal(2.34)\n\tfmt.Println(string(fltB))\n\n\tstrB, _ := json.Marshal(\"gopher\")\n\tfmt.Println(string(strB))\n\n\t// And here are some for slices and maps, which encode\n\t// to JSON arrays and objects as you'd expect.\n\tslcD := []string{\"apple\", \"peach\", \"pear\"}\n\tslcB, _ := json.Marshal(slcD)\n\tfmt.Println(string(slcB))"}]}],"commands":[],"reference":[{"path":"json.go","text":"// Go offers built-in support for JSON encoding and\n// decoding, including to and from built-in and custom\n// data types.\n\npackage main\n\nimport (\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"os\"\n)\n\n// We'll use these two structs to demonstrate encoding and\n// decoding of custom types below.\ntype response1 struct {\n\tPage   int\n\tFruits []string\n}\n\n// Only exported fields will be encoded/decoded in JSON.\n// Fields must start with capital letters to be exported.\ntype response2 struct {\n\tPage   int      `json:\"page\"`\n\tFruits []string `json:\"fruits\"`\n}\n\nfunc main() {\n    // TODO\n\t// First we'll look at encoding basic data types to\n\t// JSON strings. Here are some examples for atomic\n\t// values.\n\t// And here are some for slices and maps, which encode\n\t// to JSON arrays and objects as you'd expect.\n\t// The JSON package can automatically encode your\n\t// custom data types. It will only include exported\n\t// fields in the encoded output and will by default\n\t// use those names as the JSON keys.\n\t// You can use tags on struct field declarations\n\t// to customize the encoded JSON key names. Check the\n\t// definition of `response2` above to see an example\n\t// of such tags.\n\t// Now let's look at decoding JSON data into Go\n\t// values. Here's an example for a generic data\n\t// structure.\n\t// We need to provide a variable where the JSON\n\t// package can put the decoded data. This\n\t// `map[string]interface{}` will hold a map of strings\n\t// to arbitrary data types.\n\t// Here's the actual decoding, and a check for\n\t// associated errors.\n\t// In order to use the values in the decoded map,\n\t// we'll need to convert them to their appropriate type.\n\t// For example here we convert the value in `num` to\n\t// the expected `float64` type.\n\t// Accessing nested data requires a series of\n\t// conversions.\n\t// We can also decode JSON into custom data types.\n\t// This has the advantages of adding additional\n\t// type-safety to our programs and eliminating the\n\t// need for type assertions when accessing the decoded\n\t// data.\n\t// In the examples above we always used bytes and\n\t// strings as intermediates between the data and\n\t// JSON representation on standard out. We can also\n\t// stream JSON encodings directly to `os.Writer`s like\n\t// `os.Stdout` or even HTTP response bodies.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-concise-go-text-transformation-program":{"intro":"The Line Filters lab is a common type of program that reads input on stdin, processes it, and then prints some derived result to stdout. The purpose of this lab is to write a Go program that reads input text and modifies it according to specific requirements.","steps":[{"title":"Line Filters","body":["The problem to be solved in this lab is to write a Go program that reads input text from stdin, capitalizes all the letters in the text, and then prints the modified text to stdout.","• The program must read input text from stdin. • The program must capitalize all the letters in the input text. • The program must print the modified text to stdout."],"code":[{"lang":"sh","text":"# To try out our line filter, first make a file with a few\n# lowercase lines.\n$ echo 'hello' > /tmp/lines\n$ echo 'filter' >> /tmp/lines\n\n# Then use the line filter to get uppercase lines.\n$ cat /tmp/lines | go run line-filters.go\nHELLO\nFILTER"},{"lang":"go","text":"// A _line filter_ is a common type of program that reads\n// input on stdin, processes it, and then prints some\n// derived result to stdout. `grep` and `sed` are common\n// line filters.\n\n// Here's an example line filter in Go that writes a\n// capitalized version of all input text. You can use this\n// pattern to write your own Go line filters.\npackage main\n\nimport (\n\t\"bufio\"\n\t\"fmt\"\n\t\"os\"\n\t\"strings\"\n)\n\nfunc main() {\n\n\t// Wrapping the unbuffered `os.Stdin` with a buffered\n\t// scanner gives us a convenient `Scan` method that\n\t// advances the scanner to the next token; which is\n\t// the next line in the default scanner.\n\tscanner := bufio.NewScanner(os.Stdin)\n\n\tfor scanner.Scan() {\n\t\t// `Text` returns the current token, here the next line,\n\t\t// from the input.\n\t\tucl := strings.ToUpper(scanner.Text())\n\n\t\t// Write out the uppercased line.\n\t\tfmt.Println(ucl)\n\t}\n\n\t// Check for errors during `Scan`. End of file is\n\t// expected and not reported by `Scan` as an error.\n\tif err := scanner.Err(); err != nil {\n\t\tfmt.Fprintln(os.Stderr, \"error:\", err)\n\t\tos.Exit(1)\n\t}\n}"}]}],"commands":["echo 'hello' > /tmp/lines","echo 'filter' >> /tmp/lines","cat /tmp/lines | go run line-filters.go"],"reference":[{"path":"line-filters.go","text":"// A _line filter_ is a common type of program that reads\n// input on stdin, processes it, and then prints some\n// derived result to stdout. `grep` and `sed` are common\n// line filters.\n\n// Here's an example line filter in Go that writes a\n// capitalized version of all input text. You can use this\n// pattern to write your own Go line filters.\npackage main\n\nimport (\n\t\"bufio\"\n\t\"fmt\"\n\t\"os\"\n\t\"strings\"\n)\n\nfunc main() {\n    // TODO\n\t// Wrapping the unbuffered `os.Stdin` with a buffered\n\t// scanner gives us a convenient `Scan` method that\n\t// advances the scanner to the next token; which is\n\t// the next line in the default scanner.\n\t// `Text` returns the current token, here the next line,\n\t// from the input.\n\t// Write out the uppercased line.\n\t// Check for errors during `Scan`. End of file is\n\t// expected and not reported by `Scan` as an error.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-programming-language-methods":{"intro":"This lab aims to test the knowledge of the Go programming language's method feature.","steps":[{"title":"Methods","body":["The code provided defines a struct type called rect with two fields, width and height. Two methods are defined for this struct type, area and perim. The area method calculates the area of the rectangle, and the perim method calculates the perimeter of the rectangle. The main function calls these two methods and prints their results.","• The area method should have a receiver type of *rect. • The perim method should have a receiver type of rect. • The area method should return the area of the rectangle. • The perim method should return the perimeter of the rectangle. • The main function should call both methods and print their results."],"code":[{"lang":"sh","text":"$ go run methods.go\narea: 50\nperim: 30\narea: 50\nperim: 30\n\n# Next we'll look at Go's mechanism for grouping and\n# naming related sets of methods: interfaces."},{"lang":"go","text":"// Go supports _methods_ defined on struct types.\n\npackage main\n\nimport \"fmt\"\n\ntype rect struct {\n\twidth, height int\n}\n\n// This `area` method has a _receiver type_ of `*rect`.\nfunc (r *rect) area() int {\n\treturn r.width * r.height\n}\n\n// Methods can be defined for either pointer or value\n// receiver types. Here's an example of a value receiver.\nfunc (r rect) perim() int {\n\treturn 2*r.width + 2*r.height\n}\n\nfunc main() {\n\tr := rect{width: 10, height: 5}\n\n\t// Here we call the 2 methods defined for our struct.\n\tfmt.Println(\"area: \", r.area())\n\tfmt.Println(\"perim:\", r.perim())\n\n\t// Go automatically handles conversion between values\n\t// and pointers for method calls. You may want to use\n\t// a pointer receiver type to avoid copying on method\n\t// calls or to allow the method to mutate the\n\t// receiving struct.\n\trp := &r\n\tfmt.Println(\"area: \", rp.area())\n\tfmt.Println(\"perim:\", rp.perim())\n}"}]}],"commands":["go run methods.go"],"reference":[{"path":"methods.go","text":"// Go supports _methods_ defined on struct types.\n\npackage main\n\nimport \"fmt\"\n\ntype rect struct {\n\twidth, height int\n}\n\n// This `area` method has a _receiver type_ of `*rect`.\nfunc main() {\n    // TODO\n\n// Methods can be defined for either pointer or value\n\n// receiver types. Here's an example of a value receiver.\n\t// Here we call the 2 methods defined for our struct.\n\t// Go automatically handles conversion between values\n\t// and pointers for method calls. You may want to use\n\t// a pointer receiver type to avoid copying on method\n\t// calls or to allow the method to mutate the\n\t// receiving struct.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-error-handling-proficiency":{"intro":"The panic lab is designed to test your ability to handle unexpected errors in Golang.","steps":[{"title":"Panic","body":["The lab requires you to use the panic function to fail fast on errors that shouldn't occur during normal operation or that you aren't prepared to handle gracefully.","• Basic knowledge of Golang programming language. • Familiarity with error handling in Golang. • Understanding of the panic function in Golang."],"code":[{"lang":"sh","text":"# Running this program will cause it to panic, print\n# an error message and goroutine traces, and exit with\n# a non-zero status.\n\n# When first panic in `main` fires, the program exits\n# without reaching the rest of the code. If you'd like\n# to see the program try to create a temp file, comment\n# the first panic out.\n$ go run panic.go\npanic: a problem\n\ngoroutine 1 [running]:\nmain.main() /.../panic.go:12 +0x47\n...\nexit status 2\n\n# Note that unlike some languages which use exceptions\n# for handling of many errors, in Go it is idiomatic\n# to use error-indicating return values wherever possible."},{"lang":"go","text":"// A `panic` typically means something went unexpectedly\n// wrong. Mostly we use it to fail fast on errors that\n// shouldn't occur during normal operation, or that we\n// aren't prepared to handle gracefully.\n\npackage main\n\nimport \"os\"\n\nfunc main() {\n\n\t// We'll use panic throughout this site to check for\n\t// unexpected errors. This is the only program on the\n\t// site designed to panic.\n\tpanic(\"a problem\")\n\n\t// A common use of panic is to abort if a function\n\t// returns an error value that we don't know how to\n\t// (or want to) handle. Here's an example of\n\t// `panic`king if we get an unexpected error when creating a new file.\n\t_, err := os.Create(\"/tmp/file\")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n}"}]}],"commands":["go run panic.go"],"reference":[{"path":"panic.go","text":"// A `panic` typically means something went unexpectedly\n// wrong. Mostly we use it to fail fast on errors that\n// shouldn't occur during normal operation, or that we\n// aren't prepared to handle gracefully.\n\npackage main\n\nimport \"os\"\n\nfunc main() {\n    // TODO\n\t// We'll use panic throughout this site to check for\n\t// unexpected errors. This is the only program on the\n\t// site designed to panic.\n\t// A common use of panic is to abort if a function\n\t// returns an error value that we don't know how to\n\t// (or want to) handle. Here's an example of\n\t// `panic`king if we get an unexpected error when creating a new file.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-pointers-comprehension":{"intro":"This lab will test your understanding of pointers in Golang. Pointers are used to pass references to values and records within your program.","steps":[{"title":"Pointers","body":["The problem is to understand how pointers work in contrast to values with two functions: zeroval and zeroptr. zeroval has an int parameter, so arguments will be passed to it by value. zeroval will get a copy of ival distinct from the one in the calling function. zeroptr in contrast has an *int parameter, meaning that it takes an int pointer. The *iptr code in the function body then _dereferences_ the pointer from its memory address to the current value at that address. Assigning a value to a dereferenced pointer changes the value at the referenced address.","• You should have a basic understanding of Golang. • You should know how to define and use functions in Golang. • You should know how to use pointers in Golang."],"code":[{"lang":"sh","text":"# `zeroval` doesn't change the `i` in `main`, but\n# `zeroptr` does because it has a reference to\n# the memory address for that variable.\n$ go run pointers.go\ninitial: 1\nzeroval: 1\nzeroptr: 0\npointer: 0x42131100"},{"lang":"go","text":"// Go supports <em><a href=\"https://en.wikipedia.org/wiki/Pointer_(computer_programming)\">pointers</a></em>,\n// allowing you to pass references to values and records\n// within your program.\n\npackage main\n\nimport \"fmt\"\n\n// We'll show how pointers work in contrast to values with\n// 2 functions: `zeroval` and `zeroptr`. `zeroval` has an\n// `int` parameter, so arguments will be passed to it by\n// value. `zeroval` will get a copy of `ival` distinct\n// from the one in the calling function.\nfunc zeroval(ival int) {\n\tival = 0\n}\n\n// `zeroptr` in contrast has an `*int` parameter, meaning\n// that it takes an `int` pointer. The `*iptr` code in the\n// function body then _dereferences_ the pointer from its\n// memory address to the current value at that address.\n// Assigning a value to a dereferenced pointer changes the\n// value at the referenced address.\nfunc zeroptr(iptr *int) {\n\t*iptr = 0\n}\n\nfunc main() {\n\ti := 1\n\tfmt.Println(\"initial:\", i)\n\n\tzeroval(i)\n\tfmt.Println(\"zeroval:\", i)\n\n\t// The `&i` syntax gives the memory address of `i`,\n\t// i.e. a pointer to `i`.\n\tzeroptr(&i)\n\tfmt.Println(\"zeroptr:\", i)\n\n\t// Pointers can be printed too.\n\tfmt.Println(\"pointer:\", &i)\n}"}]}],"commands":["go run pointers.go"],"reference":[{"path":"pointers.go","text":"// Go supports <em><a href=\"https://en.wikipedia.org/wiki/Pointer_(computer_programming)\">pointers</a></em>,\n// allowing you to pass references to values and records\n// within your program.\n\npackage main\n\nimport \"fmt\"\n\n// We'll show how pointers work in contrast to values with\n// 2 functions: `zeroval` and `zeroptr`. `zeroval` has an\n// `int` parameter, so arguments will be passed to it by\n// value. `zeroval` will get a copy of `ival` distinct\n// from the one in the calling function.\nfunc main() {\n    // TODO\n\n// `zeroptr` in contrast has an `*int` parameter, meaning\n\n// that it takes an `int` pointer. The `*iptr` code in the\n\n// function body then _dereferences_ the pointer from its\n\n// memory address to the current value at that address.\n\n// Assigning a value to a dereferenced pointer changes the\n\n// value at the referenced address.\n\t// The `&i` syntax gives the memory address of `i`,\n\t// i.e. a pointer to `i`.\n\t// Pointers can be printed too.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-exploring-go-s-range-keyword":{"intro":"The range keyword is used to iterate over elements in a variety of data structures in Golang. In this lab, we will explore how to use range with different data structures.","steps":[{"title":"Range","body":["The problem to be solved in this lab is to demonstrate how to use range with slices, arrays, maps, and strings.","To complete this lab, you will need:","• Basic knowledge of Golang syntax • Golang installed on your machine"],"code":[{"lang":"sh","text":"$ go run range.go\nsum: 9\nindex: 1\na - > apple\nb - > banana\nkey: a\nkey: b\n0 103\n1 111"},{"lang":"go","text":"// _range_ iterates over elements in a variety of data\n// structures. Let's see how to use `range` with some\n// of the data structures we've already learned.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Here we use `range` to sum the numbers in a slice.\n\t// Arrays work like this too.\n\tnums := []int{2, 3, 4}\n\tsum := 0\n\tfor _, num := range nums {\n\t\tsum += num\n\t}\n\tfmt.Println(\"sum:\", sum)\n\n\t// `range` on arrays and slices provides both the\n\t// index and value for each entry. Above we didn't\n\t// need the index, so we ignored it with the\n\t// blank identifier `_`. Sometimes we actually want\n\t// the indexes though.\n\tfor i, num := range nums {\n\t\tif num == 3 {\n\t\t\tfmt.Println(\"index:\", i)\n\t\t}\n\t}\n\n\t// `range` on map iterates over key/value pairs.\n\tkvs := map[string]string{\"a\": \"apple\", \"b\": \"banana\"}\n\tfor k, v := range kvs {\n\t\tfmt.Printf(\"%s -> %s\\n\", k, v)\n\t}\n\n\t// `range` can also iterate over just the keys of a map.\n\tfor k := range kvs {\n\t\tfmt.Println(\"key:\", k)\n\t}\n\n\t// `range` on strings iterates over Unicode code\n\t// points. The first value is the starting byte index\n\t// of the `rune` and the second the `rune` itself.\n\t// See [Strings and Runes](strings-and-runes) for more\n\t// details.\n\tfor i, c := range \"go\" {\n\t\tfmt.Println(i, c)"}]}],"commands":["go run range.go"],"reference":[{"path":"range.go","text":"// _range_ iterates over elements in a variety of data\n// structures. Let's see how to use `range` with some\n// of the data structures we've already learned.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    // TODO\n\t// Here we use `range` to sum the numbers in a slice.\n\t// Arrays work like this too.\n\t// `range` on arrays and slices provides both the\n\t// index and value for each entry. Above we didn't\n\t// need the index, so we ignored it with the\n\t// blank identifier `_`. Sometimes we actually want\n\t// the indexes though.\n\t// `range` on map iterates over key/value pairs.\n\t// `range` can also iterate over just the keys of a map.\n\t// `range` on strings iterates over Unicode code\n\t// points. The first value is the starting byte index\n\t// of the `rune` and the second the `rune` itself.\n\t// See [Strings and Runes](strings-and-runes) for more\n\t// details.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-handling-panics-with-golang-recover":{"intro":"In Golang, recover is a built-in function that can be used to recover from a panic. This lab will test your ability to use recover to handle panics.","steps":[{"title":"Recover","body":["The mayPanic function in the provided code will panic when called. Your task is to modify the main function to recover from the panic and print the error message.","• Use the recover function to handle the panic in the mayPanic function. • Print the error message when a panic occurs."],"code":[{"lang":"sh","text":"$ go run recover.go\nRecovered. Error:\na problem"},{"lang":"go","text":"// Go makes it possible to _recover_ from a panic, by\n// using the `recover` built-in function. A `recover` can\n// stop a `panic` from aborting the program and let it\n// continue with execution instead.\n\n// An example of where this can be useful: a server\n// wouldn't want to crash if one of the client connections\n// exhibits a critical error. Instead, the server would\n// want to close that connection and continue serving\n// other clients. In fact, this is what Go's `net/http`\n// does by default for HTTP servers.\n\npackage main\n\nimport \"fmt\"\n\n// This function panics.\nfunc mayPanic() {\n\tpanic(\"a problem\")\n}\n\nfunc main() {\n\t// `recover` must be called within a deferred function.\n\t// When the enclosing function panics, the defer will\n\t// activate and a `recover` call within it will catch\n\t// the panic.\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\t// The return value of `recover` is the error raised in\n\t\t\t// the call to `panic`.\n\t\t\tfmt.Println(\"Recovered. Error:\\n\", r)\n\t\t}\n\t}()\n\n\tmayPanic()\n\n\t// This code will not run, because `mayPanic` panics.\n\t// The execution of `main` stops at the point of the\n\t// panic and resumes in the deferred closure.\n\tfmt.Println(\"After mayPanic()\")\n}"}]}],"commands":["go run recover.go"],"reference":[{"path":"recover.go","text":"// Go makes it possible to _recover_ from a panic, by\n// using the `recover` built-in function. A `recover` can\n// stop a `panic` from aborting the program and let it\n// continue with execution instead.\n\n// An example of where this can be useful: a server\n// wouldn't want to crash if one of the client connections\n// exhibits a critical error. Instead, the server would\n// want to close that connection and continue serving\n// other clients. In fact, this is what Go's `net/http`\n// does by default for HTTP servers.\n\npackage main\n\nimport \"fmt\"\n\n// This function panics.\nfunc main() {\n    // TODO\n\t// `recover` must be called within a deferred function.\n\t// When the enclosing function panics, the defer will\n\t// activate and a `recover` call within it will catch\n\t// the panic.\n\t// The return value of `recover` is the error raised in\n\t// the call to `panic`.\n\t// This code will not run, because `mayPanic` panics.\n\t// The execution of `main` stops at the point of the\n\t// panic and resumes in the deferred closure.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-recursive-functions-in-golang":{"intro":"This lab will test your understanding of recursive functions in Golang.","steps":[{"title":"Recursion","body":["The sum function takes an integer slice and returns the sum of all the integers in the slice. However, the function is incomplete and needs to be implemented using recursion.","• The sum function must be implemented using recursion. • The function must take an integer slice as input. • The function must return the sum of all the integers in the slice."],"code":[{"lang":"sh","text":"$ go run recursion.go\n5040\n13"},{"lang":"go","text":"// Go supports\n// <a href=\"https://en.wikipedia.org/wiki/Recursion_(computer_science)\"><em>recursive functions</em></a>.\n// Here's a classic example.\n\npackage main\n\nimport \"fmt\"\n\n// This `fact` function calls itself until it reaches the\n// base case of `fact(0)`.\nfunc fact(n int) int {\n\tif n == 0 {\n\t\treturn 1\n\t}\n\treturn n * fact(n-1)\n}\n\nfunc main() {\n\tfmt.Println(fact(7))\n\n\t// Closures can also be recursive, but this requires the\n\t// closure to be declared with a typed `var` explicitly\n\t// before it's defined.\n\tvar fib func(n int) int\n\n\tfib = func(n int) int {\n\t\tif n < 2 {\n\t\t\treturn n\n\t\t}\n\n\t\t// Since `fib` was previously declared in `main`, Go\n\t\t// knows which function to call with `fib` here.\n\t\treturn fib(n-1) + fib(n-2)\n\t}\n\n\tfmt.Println(fib(7))\n}"}]}],"commands":["go run recursion.go"],"reference":[{"path":"recursion.go","text":"// Go supports\n// <a href=\"https://en.wikipedia.org/wiki/Recursion_(computer_science)\"><em>recursive functions</em></a>.\n// Here's a classic example.\n\npackage main\n\nimport \"fmt\"\n\n// This `fact` function calls itself until it reaches the\n// base case of `fact(0)`.\nfunc main() {\n    // TODO\n\t// Closures can also be recursive, but this requires the\n\t// closure to be declared with a typed `var` explicitly\n\t// before it's defined.\n\t// Since `fib` was previously declared in `main`, Go\n\t// knows which function to call with `fib` here.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-regular-expression-tutorial":{"intro":"This lab demonstrates how to use regular expressions in Golang.","steps":[{"title":"Regular Expressions","body":["The lab requires you to complete the code to perform various regular expression-related tasks in Golang.","• Use the regexp package to perform regular expression-related tasks. • Use MatchString to test whether a pattern matches a string. • Use Compile to optimize a Regexp struct. • Use MatchString to test a match like Compile. • Use FindString to find the match for the regexp. • Use FindStringIndex to find the first match and return the start and end indexes for the match instead of the matching text. • Use FindStringSubmatch to return information for both p([a-z]+)ch and ([a-z]+). • Use FindStringSubmatchIndex to return information about the indexes of matches and submatches. • Use FindAllString to find all matches for a regexp. •…"],"code":[{"lang":"sh","text":"# For a complete reference on Go regular expressions check\n# the [`regexp`](https://pkg.go.dev/regexp) package docs."},{"lang":"go","text":"// Go offers built-in support for [regular expressions](https://en.wikipedia.org/wiki/Regular_expression).\n// Here are some examples of  common regexp-related tasks\n// in Go.\n\npackage main\n\nimport (\n\t\"bytes\"\n\t\"fmt\"\n\t\"regexp\"\n)\n\nfunc main() {\n\n\t// This tests whether a pattern matches a string.\n\tmatch, _ := regexp.MatchString(\"p([a-z]+)ch\", \"peach\")\n\tfmt.Println(match)\n\n\t// Above we used a string pattern directly, but for\n\t// other regexp tasks you'll need to `Compile` an\n\t// optimized `Regexp` struct.\n\tr, _ := regexp.Compile(\"p([a-z]+)ch\")\n\n\t// Many methods are available on these structs. Here's\n\t// a match test like we saw earlier.\n\tfmt.Println(r.MatchString(\"peach\"))\n\n\t// This finds the match for the regexp.\n\tfmt.Println(r.FindString(\"peach punch\"))\n\n\t// This also finds the first match but returns the\n\t// start and end indexes for the match instead of the\n\t// matching text.\n\tfmt.Println(\"idx:\", r.FindStringIndex(\"peach punch\"))\n\n\t// The `Submatch` variants include information about\n\t// both the whole-pattern matches and the submatches\n\t// within those matches. For example this will return\n\t// information for both `p([a-z]+)ch` and `([a-z]+)`.\n\tfmt.Println(r.FindStringSubmatch(\"peach punch\"))\n\n\t// Similarly this will return information about the\n\t// indexes of matches and submatches.\n\tfmt.Println(r.FindStringSubmatchIndex(\"peach punch\"))\n\n\t// The `All` variants of these functions apply to all\n\t// matches in the input, not just the first. For\n\t// example to find all matches for a regexp."}]}],"commands":[],"reference":[{"path":"regular-expressions.go","text":"// Go offers built-in support for [regular expressions](https://en.wikipedia.org/wiki/Regular_expression).\n// Here are some examples of  common regexp-related tasks\n// in Go.\n\npackage main\n\nimport (\n\t\"bytes\"\n\t\"fmt\"\n\t\"regexp\"\n)\n\nfunc main() {\n    // TODO\n\t// This tests whether a pattern matches a string.\n\t// Above we used a string pattern directly, but for\n\t// other regexp tasks you'll need to `Compile` an\n\t// optimized `Regexp` struct.\n\t// Many methods are available on these structs. Here's\n\t// a match test like we saw earlier.\n\t// This finds the match for the regexp.\n\t// This also finds the first match but returns the\n\t// start and end indexes for the match instead of the\n\t// matching text.\n\t// The `Submatch` variants include information about\n\t// both the whole-pattern matches and the submatches\n\t// within those matches. For example this will return\n\t// information for both `p([a-z]+)ch` and `([a-z]+)`.\n\t// Similarly this will return information about the\n\t// indexes of matches and submatches.\n\t// The `All` variants of these functions apply to all\n\t// matches in the input, not just the first. For\n\t// example to find all matches for a regexp.\n\t// These `All` variants are available for the other\n\t// functions we saw above as well.\n\t// Providing a non-negative integer as the second\n\t// argument to these functions will limit the number\n\t// of matches.\n\t// Our examples above had string arguments and used\n\t// names like `MatchString`. We can also provide\n\t// `[]byte` arguments and drop `String` from the\n\t// function name.\n\t// When creating global variables with regular\n\t// expressions you can use the `MustCompile` variation\n\t// of `Compile`. `MustCompile` panics instead of\n\t// returning an error, which makes it safer to use for\n\t// global variables.\n\t// The `regexp` package can also be used to replace\n\t// subsets of strings with other values.\n\t// The `Func` variant allows you to transform matched\n\t// text with a given function.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-select-statement-demonstration":{"intro":"This lab aims to test your knowledge of Go's select statement, which allows you to wait on multiple channel operations.","steps":[{"title":"Select","body":["In this lab, you are given two channels, c1 and c2, which will receive a value after some amount of time. Your task is to use select to await both of these values simultaneously, printing each one as it arrives.","• You should use the select statement to wait on both channels. • You should print the value received from each channel as it arrives."],"code":[{"lang":"sh","text":"# We receive the values `\"one\"` and then `\"two\"` as\n# expected.\n$ time go run select.go\nreceived one\nreceived two\n\n# Note that the total execution time is only ~2 seconds\n# since both the 1 and 2 second `Sleeps` execute\n# concurrently.\nreal 0m2.245s"},{"lang":"go","text":"// Go's _select_ lets you wait on multiple channel\n// operations. Combining goroutines and channels with\n// select is a powerful feature of Go.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n\n\t// For our example we'll select across two channels.\n\tc1 := make(chan string)\n\tc2 := make(chan string)\n\n\t// Each channel will receive a value after some amount\n\t// of time, to simulate e.g. blocking RPC operations\n\t// executing in concurrent goroutines.\n\tgo func() {\n\t\ttime.Sleep(1 * time.Second)\n\t\tc1 <- \"one\"\n\t}()\n\tgo func() {\n\t\ttime.Sleep(2 * time.Second)\n\t\tc2 <- \"two\"\n\t}()\n\n\t// We'll use `select` to await both of these values\n\t// simultaneously, printing each one as it arrives.\n\tfor i := 0; i < 2; i++ {\n\t\tselect {\n\t\tcase msg1 := <-c1:\n\t\t\tfmt.Println(\"received\", msg1)\n\t\tcase msg2 := <-c2:\n\t\t\tfmt.Println(\"received\", msg2)\n\t\t}\n\t}\n}"}]}],"commands":[],"reference":[{"path":"select.go","text":"// Go's _select_ lets you wait on multiple channel\n// operations. Combining goroutines and channels with\n// select is a powerful feature of Go.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n    // TODO\n\t// For our example we'll select across two channels.\n\t// Each channel will receive a value after some amount\n\t// of time, to simulate e.g. blocking RPC operations\n\t// executing in concurrent goroutines.\n\t// We'll use `select` to await both of these values\n\t// simultaneously, printing each one as it arrives.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-handling-unix-signals-in-go":{"intro":"The Signals lab demonstrates how to handle Unix signals in Go programs using channels.","steps":[{"title":"Signals","body":["In some cases, we want our Go programs to handle Unix signals intelligently. For instance, we might want a server to shut down gracefully when it receives a SIGTERM, or a command-line tool to stop processing input if it receives a SIGINT.","• Create a buffered channel to receive os.Signal notifications. • Register the channel to receive notifications of specified signals using signal.Notify. • Create a goroutine to execute a blocking receive for signals. • Print out the received signal and notify the program that it can finish. • Wait for the expected signal and then exit."],"code":[{"lang":"sh","text":"# When we run this program it will block waiting for a\n# signal. By typing `ctrl-C` (which the\n# terminal shows as `^C`) we can send a `SIGINT` signal,\n# causing the program to print `interrupt` and then exit.\n$ go run signals.go\nawaiting signal\n^C\ninterrupt\nexiting"},{"lang":"go","text":"// Sometimes we'd like our Go programs to intelligently\n// handle [Unix signals](https://en.wikipedia.org/wiki/Unix_signal).\n// For example, we might want a server to gracefully\n// shutdown when it receives a `SIGTERM`, or a command-line\n// tool to stop processing input if it receives a `SIGINT`.\n// Here's how to handle signals in Go with channels.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"os/signal\"\n\t\"syscall\"\n)\n\nfunc main() {\n\n\t// Go signal notification works by sending `os.Signal`\n\t// values on a channel. We'll create a channel to\n\t// receive these notifications. Note that this channel\n\t// should be buffered.\n\tsigs := make(chan os.Signal, 1)\n\n\t// `signal.Notify` registers the given channel to\n\t// receive notifications of the specified signals.\n\tsignal.Notify(sigs, syscall.SIGINT, syscall.SIGTERM)\n\n\t// We could receive from `sigs` here in the main\n\t// function, but let's see how this could also be\n\t// done in a separate goroutine, to demonstrate\n\t// a more realistic scenario of graceful shutdown.\n\tdone := make(chan bool, 1)\n\n\tgo func() {\n\t\t// This goroutine executes a blocking receive for\n\t\t// signals. When it gets one it'll print it out\n\t\t// and then notify the program that it can finish.\n\t\tsig := <-sigs\n\t\tfmt.Println()\n\t\tfmt.Println(sig)\n\t\tdone <- true\n\t}()\n\n\t// The program will wait here until it gets the\n\t// expected signal (as indicated by the goroutine\n\t// above sending a value on `done`) and then exit.\n\tfmt.Println(\"awaiting signal\")"}]}],"commands":["go run signals.go"],"reference":[{"path":"signals.go","text":"// Sometimes we'd like our Go programs to intelligently\n// handle [Unix signals](https://en.wikipedia.org/wiki/Unix_signal).\n// For example, we might want a server to gracefully\n// shutdown when it receives a `SIGTERM`, or a command-line\n// tool to stop processing input if it receives a `SIGINT`.\n// Here's how to handle signals in Go with channels.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"os/signal\"\n\t\"syscall\"\n)\n\nfunc main() {\n    // TODO\n\t// Go signal notification works by sending `os.Signal`\n\t// values on a channel. We'll create a channel to\n\t// receive these notifications. Note that this channel\n\t// should be buffered.\n\t// `signal.Notify` registers the given channel to\n\t// receive notifications of the specified signals.\n\t// We could receive from `sigs` here in the main\n\t// function, but let's see how this could also be\n\t// done in a separate goroutine, to demonstrate\n\t// a more realistic scenario of graceful shutdown.\n\t// This goroutine executes a blocking receive for\n\t// signals. When it gets one it'll print it out\n\t// and then notify the program that it can finish.\n\t// The program will wait here until it gets the\n\t// expected signal (as indicated by the goroutine\n\t// above sending a value on `done`) and then exit.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-slices-a-hands-on":{"intro":"The Slices lab is designed to test your knowledge of the slice data type in Go. Slices are a more powerful interface to sequences than arrays, and this lab will help you understand how to use them.","steps":[{"title":"Slices","body":["The problem to be solved in this lab is to create and manipulate slices in Go. You will need to create an empty slice with non-zero length, set and get values in the slice, use the len function to get the length of the slice, use the append function to add new values to the slice, use the copy function to copy a slice, and use the slice operator to get a slice of elements from an existing slice.","To complete this lab, you will need to have a basic understanding of Go syntax and the slice data type. You will also need to be familiar with the make, append, and copy functions, as well as the slice operator."],"code":[{"lang":"sh","text":"# Note that while slices are different types than arrays,\n# they are rendered similarly by `fmt.Println`.\n$ go run slices.go\nemp: [ ]\nset: [a b c]\nget: c\nlen: 3\napd: [a b c d e f]\ncpy: [a b c d e f]\nsl1: [c d e]\nsl2: [a b c d e]\nsl3: [c d e f]\ndcl: [g h i]\n2d: [[0] [1 2] [2 3 4]]\n\n# Check out this [great blog post](https://go.dev/blog/slices-intro)\n# by the Go team for more details on the design and\n# implementation of slices in Go.\n\n# Now that we've seen arrays and slices we'll look at\n# Go's other key builtin data structure: maps."},{"lang":"go","text":"// _Slices_ are an important data type in Go, giving\n// a more powerful interface to sequences than arrays.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n\n\t// Unlike arrays, slices are typed only by the\n\t// elements they contain (not the number of elements).\n\t// To create an empty slice with non-zero length, use\n\t// the builtin `make`. Here we make a slice of\n\t// `string`s of length `3` (initially zero-valued).\n\ts := make([]string, 3)\n\tfmt.Println(\"emp:\", s)\n\n\t// We can set and get just like with arrays.\n\ts[0] = \"a\"\n\ts[1] = \"b\"\n\ts[2] = \"c\"\n\tfmt.Println(\"set:\", s)\n\tfmt.Println(\"get:\", s[2])\n\n\t// `len` returns the length of the slice as expected.\n\tfmt.Println(\"len:\", len(s))\n\n\t// In addition to these basic operations, slices\n\t// support several more that make them richer than\n\t// arrays. One is the builtin `append`, which\n\t// returns a slice containing one or more new values.\n\t// Note that we need to accept a return value from\n\t// `append` as we may get a new slice value.\n\ts = append(s, \"d\")\n\ts = append(s, \"e\", \"f\")\n\tfmt.Println(\"apd:\", s)\n\n\t// Slices can also be `copy`'d. Here we create an\n\t// empty slice `c` of the same length as `s` and copy\n\t// into `c` from `s`.\n\tc := make([]string, len(s))\n\tcopy(c, s)\n\tfmt.Println(\"cpy:\", c)\n\n\t// Slices support a \"slice\" operator with the syntax\n\t// `slice[low:high]`. For example, this gets a slice\n\t// of the elements `s[2]`, `s[3]`, and `s[4]`.\n\tl := s[2:5]"}]}],"commands":["go run slices.go"],"reference":[{"path":"slices.go","text":"// _Slices_ are an important data type in Go, giving\n// a more powerful interface to sequences than arrays.\n\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    // TODO\n\t// Unlike arrays, slices are typed only by the\n\t// elements they contain (not the number of elements).\n\t// To create an empty slice with non-zero length, use\n\t// the builtin `make`. Here we make a slice of\n\t// `string`s of length `3` (initially zero-valued).\n\t// We can set and get just like with arrays.\n\t// `len` returns the length of the slice as expected.\n\t// In addition to these basic operations, slices\n\t// support several more that make them richer than\n\t// arrays. One is the builtin `append`, which\n\t// returns a slice containing one or more new values.\n\t// Note that we need to accept a return value from\n\t// `append` as we may get a new slice value.\n\t// Slices can also be `copy`'d. Here we create an\n\t// empty slice `c` of the same length as `s` and copy\n\t// into `c` from `s`.\n\t// Slices support a \"slice\" operator with the syntax\n\t// `slice[low:high]`. For example, this gets a slice\n\t// of the elements `s[2]`, `s[3]`, and `s[4]`.\n\t// This slices up to (but excluding) `s[5]`.\n\t// And this slices up from (and including) `s[2]`.\n\t// We can declare and initialize a variable for slice\n\t// in a single line as well.\n\t// Slices can be composed into multi-dimensional data\n\t// structures. The length of the inner slices can\n\t// vary, unlike with multi-dimensional arrays.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-concurrent-goroutine-synchronization":{"intro":"This lab aims to demonstrate how to use channels and goroutines to synchronize access to shared state across multiple goroutines.","steps":[{"title":"Stateful Goroutines","body":["In concurrent programming, it is essential to synchronize access to shared state to avoid race conditions and data corruption. This lab presents a scenario where a single goroutine owns the state, and other goroutines send messages to read or write the state.","• Use channels to issue read and write requests to the state-owning goroutine. • Use readOp and writeOp structs to encapsulate requests and responses. • Use a map to store the state. • Use resp channels to indicate success and return values. • Use atomic package to count read and write operations. • Use time package to add a delay between operations."],"code":[{"lang":"sh","text":"# Running our program shows that the goroutine-based\n# state management example completes about 80,000\n# total operations.\n$ go run stateful-goroutines.go\nreadOps: 71708\nwriteOps: 7177\n\n# For this particular case the goroutine-based approach\n# was a bit more involved than the mutex-based one. It\n# might be useful in certain cases though, for example\n# where you have other channels involved or when managing\n# multiple such mutexes would be error-prone. You should\n# use whichever approach feels most natural, especially\n# with respect to understanding the correctness of your\n# program."},{"lang":"go","text":"// In the previous example we used explicit locking with\n// [mutexes](mutexes) to synchronize access to shared state\n// across multiple goroutines. Another option is to use the\n// built-in synchronization features of  goroutines and\n// channels to achieve the same result. This channel-based\n// approach aligns with Go's ideas of sharing memory by\n// communicating and having each piece of data owned\n// by exactly 1 goroutine.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math/rand\"\n\t\"sync/atomic\"\n\t\"time\"\n)\n\n// In this example our state will be owned by a single\n// goroutine. This will guarantee that the data is never\n// corrupted with concurrent access. In order to read or\n// write that state, other goroutines will send messages\n// to the owning goroutine and receive corresponding\n// replies. These `readOp` and `writeOp` `struct`s\n// encapsulate those requests and a way for the owning\n// goroutine to respond.\ntype readOp struct {\n\tkey  int\n\tresp chan int\n}\ntype writeOp struct {\n\tkey  int\n\tval  int\n\tresp chan bool\n}\n\nfunc main() {\n\n\t// As before we'll count how many operations we perform.\n\tvar readOps uint64\n\tvar writeOps uint64\n\n\t// The `reads` and `writes` channels will be used by\n\t// other goroutines to issue read and write requests,\n\t// respectively.\n\treads := make(chan readOp)\n\twrites := make(chan writeOp)"}]}],"commands":["go run stateful-goroutines.go"],"reference":[{"path":"stateful-goroutines.go","text":"// In the previous example we used explicit locking with\n// [mutexes](mutexes) to synchronize access to shared state\n// across multiple goroutines. Another option is to use the\n// built-in synchronization features of  goroutines and\n// channels to achieve the same result. This channel-based\n// approach aligns with Go's ideas of sharing memory by\n// communicating and having each piece of data owned\n// by exactly 1 goroutine.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math/rand\"\n\t\"sync/atomic\"\n\t\"time\"\n)\n\n// In this example our state will be owned by a single\n// goroutine. This will guarantee that the data is never\n// corrupted with concurrent access. In order to read or\n// write that state, other goroutines will send messages\n// to the owning goroutine and receive corresponding\n// replies. These `readOp` and `writeOp` `struct`s\n// encapsulate those requests and a way for the owning\n// goroutine to respond.\ntype readOp struct {\n\tkey  int\n\tresp chan int\n}\ntype writeOp struct {\n\tkey  int\n\tval  int\n\tresp chan bool\n}\n\nfunc main() {\n    // TODO\n\t// As before we'll count how many operations we perform.\n\t// The `reads` and `writes` channels will be used by\n\t// other goroutines to issue read and write requests,\n\t// respectively.\n\t// Here is the goroutine that owns the `state`, which\n\t// is a map as in the previous example but now private\n\t// to the stateful goroutine. This goroutine repeatedly\n\t// selects on the `reads` and `writes` channels,\n\t// responding to requests as they arrive. A response\n\t// is executed by first performing the requested\n\t// operation and then sending a value on the response\n\t// channel `resp` to indicate success (and the desired\n\t// value in the case of `reads`).\n\t// This starts 100 goroutines to issue reads to the\n\t// state-owning goroutine via the `reads` channel.\n\t// Each read requires constructing a `readOp`, sending\n\t// it over the `reads` channel, and then receiving the\n\t// result over the provided `resp` channel.\n\t// We start 10 writes as well, using a similar\n\t// approach.\n\t// Let the goroutines work for a second.\n\t// Finally, capture and report the op counts.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-string-formatting-fundamentals-in-golang":{"intro":"This lab aims to test your knowledge of string formatting in Golang. You will be required to format different types of data such as integers, floats, strings, and structs using various formatting verbs.","steps":[{"title":"String Formatting","body":["You are required to format different types of data using various formatting verbs in Golang.","• You must use the fmt package to format the data. • You must use the correct formatting verb for each data type. • You must be able to format integers, floats, strings, and structs. • You must be able to control the width and precision of the output. • You must be able to left-justify or right-justify the output."],"code":[{"lang":"sh","text":"$ go run string-formatting.go\nstruct1: {1 2}\nstruct2: {x:1 y:2}\nstruct3: main.point{x:1, y:2}\ntype: main.point\nbool: true\nint: 123\nbin: 1110\nchar: !\nhex: 1c8\nfloat1: 78.900000\nfloat2: 1.234000e+08\nfloat3: 1.234000E+08\nstr1: \"string\"\nstr2: \"\\\"string\\\"\"\nstr3: 6865782074686973\npointer: 0xc0000ba000\nwidth1: | 12 | 345 \\\n  | width2: | 1.20 | 3.45 \\\n  | width3: | 1.20 | 3.45 \\\n  | width4: | foo | b \\\n  | width5: | foo | b \\\n  | sprintf: a string\nio: an error"},{"lang":"go","text":"// Go offers excellent support for string formatting in\n// the `printf` tradition. Here are some examples of\n// common string formatting tasks.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\ntype point struct {\n\tx, y int\n}\n\nfunc main() {\n\n\t// Go offers several printing \"verbs\" designed to\n\t// format general Go values. For example, this prints\n\t// an instance of our `point` struct.\n\tp := point{1, 2}\n\tfmt.Printf(\"struct1: %v\\n\", p)\n\n\t// If the value is a struct, the `%+v` variant will\n\t// include the struct's field names.\n\tfmt.Printf(\"struct2: %+v\\n\", p)\n\n\t// The `%#v` variant prints a Go syntax representation\n\t// of the value, i.e. the source code snippet that\n\t// would produce that value.\n\tfmt.Printf(\"struct3: %#v\\n\", p)\n\n\t// To print the type of a value, use `%T`.\n\tfmt.Printf(\"type: %T\\n\", p)\n\n\t// Formatting booleans is straight-forward.\n\tfmt.Printf(\"bool: %t\\n\", true)\n\n\t// There are many options for formatting integers.\n\t// Use `%d` for standard, base-10 formatting.\n\tfmt.Printf(\"int: %d\\n\", 123)\n\n\t// This prints a binary representation.\n\tfmt.Printf(\"bin: %b\\n\", 14)\n\n\t// This prints the character corresponding to the\n\t// given integer.\n\tfmt.Printf(\"char: %c\\n\", 33)"}]}],"commands":["go run string-formatting.go"],"reference":[{"path":"string-formatting.go","text":"// Go offers excellent support for string formatting in\n// the `printf` tradition. Here are some examples of\n// common string formatting tasks.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\ntype point struct {\n\tx, y int\n}\n\nfunc main() {\n    // TODO\n\t// Go offers several printing \"verbs\" designed to\n\t// format general Go values. For example, this prints\n\t// an instance of our `point` struct.\n\t// If the value is a struct, the `%+v` variant will\n\t// include the struct's field names.\n\t// The `%#v` variant prints a Go syntax representation\n\t// of the value, i.e. the source code snippet that\n\t// would produce that value.\n\t// To print the type of a value, use `%T`.\n\t// Formatting booleans is straight-forward.\n\t// There are many options for formatting integers.\n\t// Use `%d` for standard, base-10 formatting.\n\t// This prints a binary representation.\n\t// This prints the character corresponding to the\n\t// given integer.\n\t// `%x` provides hex encoding.\n\t// There are also several formatting options for\n\t// floats. For basic decimal formatting use `%f`.\n\t// `%e` and `%E` format the float in (slightly\n\t// different versions of) scientific notation.\n\t// For basic string printing use `%s`.\n\t// To double-quote strings as in Go source, use `%q`.\n\t// As with integers seen earlier, `%x` renders\n\t// the string in base-16, with two output characters\n\t// per byte of input.\n\t// To print a representation of a pointer, use `%p`.\n\t// When formatting numbers you will often want to\n\t// control the width and precision of the resulting\n\t// figure. To specify the width of an integer, use a\n\t// number after the `%` in the verb. By default the\n\t// result will be right-justified and padded with\n\t// spaces.\n\t// You can also specify the width of printed floats,\n\t// though usually you'll also want to restrict the\n\t// decimal precision at the same time with the\n\t// width.precision syntax.\n\t// To left-justify, use the `-` flag.\n\t// You may also want to control width when formatting\n\t// strings, especially to ensure that they align in\n\t// table-like output. For basic right-justified width.\n\t// To left-justify use the `-` flag as with numbers.\n\t// So far we've seen `Printf`, which prints the\n\t// formatted string to `os.Stdout`. `Sprintf` formats\n\t// and returns a string without printing it anywhere.\n\t// You can format+print to `io.Writers` other than\n\t// `os.Stdout` using `Fprintf`.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-string-manipulation-in-go":{"intro":"The strings package in Golang provides many useful string-related functions. This lab aims to test your understanding of some of these functions.","steps":[{"title":"String Functions","body":["Complete the code below to print the output of various string functions provided by the strings package.","• Use the strings package to complete the lab. • Use the fmt.Println function to print the output. • Do not modify the function name or parameters."],"code":[{"lang":"sh","text":"$ go run string-functions.go\nContains: true\nCount: 2\nHasPrefix: true\nHasSuffix: true\nIndex: 1\nJoin: a-b\nRepeat: aaaaa\nReplace: f00\nReplace: f0o\nSplit: [a b c d e]\nToLower: test\nToUpper: TEST"},{"lang":"go","text":"// The standard library's `strings` package provides many\n// useful string-related functions. Here are some examples\n// to give you a sense of the package.\n\npackage main\n\nimport (\n\t\"fmt\"\n\ts \"strings\"\n)\n\n// We alias `fmt.Println` to a shorter name as we'll use\n// it a lot below.\nvar p = fmt.Println\n\nfunc main() {\n\n\t// Here's a sample of the functions available in\n\t// `strings`. Since these are functions from the\n\t// package, not methods on the string object itself,\n\t// we need pass the string in question as the first\n\t// argument to the function. You can find more\n\t// functions in the [`strings`](https://pkg.go.dev/strings)\n\t// package docs.\n\tp(\"Contains:  \", s.Contains(\"test\", \"es\"))\n\tp(\"Count:     \", s.Count(\"test\", \"t\"))\n\tp(\"HasPrefix: \", s.HasPrefix(\"test\", \"te\"))\n\tp(\"HasSuffix: \", s.HasSuffix(\"test\", \"st\"))\n\tp(\"Index:     \", s.Index(\"test\", \"e\"))\n\tp(\"Join:      \", s.Join([]string{\"a\", \"b\"}, \"-\"))\n\tp(\"Repeat:    \", s.Repeat(\"a\", 5))\n\tp(\"Replace:   \", s.Replace(\"foo\", \"o\", \"0\", -1))\n\tp(\"Replace:   \", s.Replace(\"foo\", \"o\", \"0\", 1))\n\tp(\"Split:     \", s.Split(\"a-b-c-d-e\", \"-\"))\n\tp(\"ToLower:   \", s.ToLower(\"TEST\"))\n\tp(\"ToUpper:   \", s.ToUpper(\"test\"))\n}"}]}],"commands":["go run string-functions.go"],"reference":[{"path":"string-functions.go","text":"// The standard library's `strings` package provides many\n// useful string-related functions. Here are some examples\n// to give you a sense of the package.\n\npackage main\n\nimport (\n\t\"fmt\"\n\ts \"strings\"\n)\n\n// We alias `fmt.Println` to a shorter name as we'll use\n// it a lot below.\nvar p = fmt.Println\n\nfunc main() {\n    // TODO\n\t// Here's a sample of the functions available in\n\t// `strings`. Since these are functions from the\n\t// package, not methods on the string object itself,\n\t// we need pass the string in question as the first\n\t// argument to the function. You can find more\n\t// functions in the [`strings`](https://pkg.go.dev/strings)\n\t// package docs.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-golang-struct-embedding":{"intro":"This lab aims to test your understanding of struct embedding in Golang. You will be required to create a struct that embeds another struct and access its fields and methods.","steps":[{"title":"Struct Embedding","body":["Create a struct named container that embeds a struct named base. The base struct should have a field named num of type int and a method named describe() that returns a string. The container struct should have a field named str of type string. The container struct should be able to access the num field and describe() method of the base struct.","• The base struct should have a field named num of type int. • The base struct should have a method named describe() that returns a string. • The container struct should have a field named str of type string. • The container struct should embed the base struct. • The container struct should be able to access the num field and describe() method of the base struct."],"code":[{"lang":"sh","text":"$ go run struct-embedding.go\nco={num: 1, str: some name}\nalso num: 1\ndescribe: base with num=1\ndescriber: base with num=1"},{"lang":"go","text":"// Go supports _embedding_ of structs and interfaces\n// to express a more seamless _composition_ of types.\n// This is not to be confused with [`//go:embed`](embed-directive) which is\n// a go directive introduced in Go version 1.16+ to embed\n// files and folders into the application binary.\n\npackage main\n\nimport \"fmt\"\n\ntype base struct {\n\tnum int\n}\n\nfunc (b base) describe() string {\n\treturn fmt.Sprintf(\"base with num=%v\", b.num)\n}\n\n// A `container` _embeds_ a `base`. An embedding looks\n// like a field without a name.\ntype container struct {\n\tbase\n\tstr string\n}\n\nfunc main() {\n\n\t// When creating structs with literals, we have to\n\t// initialize the embedding explicitly; here the\n\t// embedded type serves as the field name.\n\tco := container{\n\t\tbase: base{\n\t\t\tnum: 1,\n\t\t},\n\t\tstr: \"some name\",\n\t}\n\n\t// We can access the base's fields directly on `co`,\n\t// e.g. `co.num`.\n\tfmt.Printf(\"co={num: %v, str: %v}\\n\", co.num, co.str)\n\n\t// Alternatively, we can spell out the full path using\n\t// the embedded type name.\n\tfmt.Println(\"also num:\", co.base.num)\n\n\t// Since `container` embeds `base`, the methods of\n\t// `base` also become methods of a `container`. Here\n\t// we invoke a method that was embedded from `base`"}]}],"commands":["go run struct-embedding.go"],"reference":[{"path":"struct-embedding.go","text":"// Go supports _embedding_ of structs and interfaces\n// to express a more seamless _composition_ of types.\n// This is not to be confused with [`//go:embed`](embed-directive) which is\n// a go directive introduced in Go version 1.16+ to embed\n// files and folders into the application binary.\n\npackage main\n\nimport \"fmt\"\n\ntype base struct {\n\tnum int\n}\n\nfunc main() {\n    // TODO\n\n// A `container` _embeds_ a `base`. An embedding looks\n\n// like a field without a name.\n\t// When creating structs with literals, we have to\n\t// initialize the embedding explicitly; here the\n\t// embedded type serves as the field name.\n\t// We can access the base's fields directly on `co`,\n\t// e.g. `co.num`.\n\t// Alternatively, we can spell out the full path using\n\t// the embedded type name.\n\t// Since `container` embeds `base`, the methods of\n\t// `base` also become methods of a `container`. Here\n\t// we invoke a method that was embedded from `base`\n\t// directly on `co`.\n\t// Embedding structs with methods may be used to bestow\n\t// interface implementations onto other structs. Here\n\t// we see that a `container` now implements the\n\t// `describer` interface because it embeds `base`.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-struct-manipulation-in-go":{"intro":"This lab aims to test your knowledge of Go's structs, which are typed collections of fields. Structs are useful for grouping data together to form records.","steps":[{"title":"Structs","body":["In this lab, you need to complete the newPerson function that constructs a new person struct with the given name. The person struct type has name and age fields.","• The person struct type must have name and age fields. • The newPerson function must construct a new person struct with the given name. • The newPerson function must return a pointer to the newly created person struct. • The main function must print the following: • A new struct with name \"Bob\" and age 20. • A new struct with name \"Alice\" and age 30. • A new struct with name \"Fred\" and age 0. • A pointer to a new struct with name \"Ann\" and age 40. • A new struct constructed using the newPerson function with name \"Jon\" and age 42. • The name field of a struct with name \"Sean\" and age 50. • The age field of a struct pointer to a…"],"code":[{"lang":"sh","text":"$ go run structs.go\n{Bob 20}\n{Alice 30}\n{Fred 0}\n&{Ann 40}\n&{Jon 42}\nSean\n50\n51"},{"lang":"go","text":"// Go's _structs_ are typed collections of fields.\n// They're useful for grouping data together to form\n// records.\n\npackage main\n\nimport \"fmt\"\n\n// This `person` struct type has `name` and `age` fields.\ntype person struct {\n\tname string\n\tage  int\n}\n\n// `newPerson` constructs a new person struct with the given name.\nfunc newPerson(name string) *person {\n\t// You can safely return a pointer to local variable\n\t// as a local variable will survive the scope of the function.\n\tp := person{name: name}\n\tp.age = 42\n\treturn &p\n}\n\nfunc main() {\n\n\t// This syntax creates a new struct.\n\tfmt.Println(person{\"Bob\", 20})\n\n\t// You can name the fields when initializing a struct.\n\tfmt.Println(person{name: \"Alice\", age: 30})\n\n\t// Omitted fields will be zero-valued.\n\tfmt.Println(person{name: \"Fred\"})\n\n\t// An `&` prefix yields a pointer to the struct.\n\tfmt.Println(&person{name: \"Ann\", age: 40})\n\n\t// It's idiomatic to encapsulate new struct creation in constructor functions\n\tfmt.Println(newPerson(\"Jon\"))\n\n\t// Access struct fields with a dot.\n\ts := person{name: \"Sean\", age: 50}\n\tfmt.Println(s.name)\n\n\t// You can also use dots with struct pointers - the\n\t// pointers are automatically dereferenced.\n\tsp := &s\n\tfmt.Println(sp.age)"}]}],"commands":["go run structs.go"],"reference":[{"path":"structs.go","text":"// Go's _structs_ are typed collections of fields.\n// They're useful for grouping data together to form\n// records.\n\npackage main\n\nimport \"fmt\"\n\n// This `person` struct type has `name` and `age` fields.\ntype person struct {\n\tname string\n\tage  int\n}\n\n// `newPerson` constructs a new person struct with the given name.\nfunc main() {\n    // TODO\n\t// You can safely return a pointer to local variable\n\t// as a local variable will survive the scope of the function.\n\t// This syntax creates a new struct.\n\t// You can name the fields when initializing a struct.\n\t// Omitted fields will be zero-valued.\n\t// An `&` prefix yields a pointer to the struct.\n\t// It's idiomatic to encapsulate new struct creation in constructor functions\n\t// Access struct fields with a dot.\n\t// You can also use dots with struct pointers - the\n\t// pointers are automatically dereferenced.\n\t// Structs are mutable.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-concise-switch-statement-explanation":{"intro":"In this lab, you will learn how to use the switch statement in Go to handle different types of input and execute corresponding code blocks.","steps":[{"title":"Switch","body":["In this lab, you need to complete the switch statement to print out the corresponding message based on the input value.","• The switch statement must be used to solve the problem. • The default case must be used to handle unexpected input values."],"code":[{"lang":"sh","text":"$ go run switch.go\nWrite 2 as two\nIt's a weekday\nIt's after noon\nI'm a bool\nI'm an int\nDon't know type string"},{"lang":"go","text":"// _Switch statements_ express conditionals across many\n// branches.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n\n\t// Here's a basic `switch`.\n\ti := 2\n\tfmt.Print(\"Write \", i, \" as \")\n\tswitch i {\n\tcase 1:\n\t\tfmt.Println(\"one\")\n\tcase 2:\n\t\tfmt.Println(\"two\")\n\tcase 3:\n\t\tfmt.Println(\"three\")\n\t}\n\n\t// You can use commas to separate multiple expressions\n\t// in the same `case` statement. We use the optional\n\t// `default` case in this example as well.\n\tswitch time.Now().Weekday() {\n\tcase time.Saturday, time.Sunday:\n\t\tfmt.Println(\"It's the weekend\")\n\tdefault:\n\t\tfmt.Println(\"It's a weekday\")\n\t}\n\n\t// `switch` without an expression is an alternate way\n\t// to express if/else logic. Here we also show how the\n\t// `case` expressions can be non-constants.\n\tt := time.Now()\n\tswitch {\n\tcase t.Hour() < 12:\n\t\tfmt.Println(\"It's before noon\")\n\tdefault:\n\t\tfmt.Println(\"It's after noon\")\n\t}\n\n\t// A type `switch` compares types instead of values.  You\n\t// can use this to discover the type of an interface\n\t// value.  In this example, the variable `t` will have the"}]}],"commands":["go run switch.go"],"reference":[{"path":"switch.go","text":"// _Switch statements_ express conditionals across many\n// branches.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n    // TODO\n\t// Here's a basic `switch`.\n\t// You can use commas to separate multiple expressions\n\t// in the same `case` statement. We use the optional\n\t// `default` case in this example as well.\n\t// `switch` without an expression is an alternate way\n\t// to express if/else logic. Here we also show how the\n\t// `case` expressions can be non-constants.\n\t// A type `switch` compares types instead of values.  You\n\t// can use this to discover the type of an interface\n\t// value.  In this example, the variable `t` will have the\n\t// type corresponding to its clause.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-dynamic-content-generation-with-golang-templ":{"intro":"In this lab, you will learn how to use the Go text/template package to generate dynamic content, including accessing struct fields, providing conditional execution, and looping through slices, arrays, maps, or channels.","steps":[{"title":"Text Templates","body":["In this lab, you are required to demonstrate the use of the text/template package to generate dynamic content.","• Use the text/template package to generate dynamic content. • Use the template.Must function to panic in case Parse returns an error. • Use the {{.FieldName}} action to access struct fields. • Use the {{if . -}} yes {{else -}} no {{end}}\\n action to provide conditional execution for templates. • Use the {{range .}}{{.}} {{end}}\\n action to loop through slices, arrays, maps, or channels."],"code":[{"lang":"sh","text":"$ go run text-templates.go\nValue: some text\nValue: 5\nValue: [Go Rust C++ C#]\nName: Jane Doe\nName: Mickey Mouse\nyes\nno\nRange: Go Rust C++ C#"},{"lang":"go","text":"// Go offers built-in support for creating dynamic content or showing customized\n// output to the user with the `text/template` package. A sibling package\n// named `html/template` provides the same API but has additional security\n// features and should be used for generating HTML.\n\npackage main\n\nimport (\n\t\"os\"\n\t\"text/template\"\n)\n\nfunc main() {\n\n\t// We can create a new template and parse its body from\n\t// a string.\n\t// Templates are a mix of static text and \"actions\" enclosed in\n\t// `{{...}}` that are used to dynamically insert content.\n\tt1 := template.New(\"t1\")\n\tt1, err := t1.Parse(\"Value is {{.}}\\n\")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\t// Alternatively, we can use the `template.Must` function to\n\t// panic in case `Parse` returns an error. This is especially\n\t// useful for templates initialized in the global scope.\n\tt1 = template.Must(t1.Parse(\"Value: {{.}}\\n\"))\n\n\t// By \"executing\" the template we generate its text with\n\t// specific values for its actions. The `{{.}}` action is\n\t// replaced by the value passed as a parameter to `Execute`.\n\tt1.Execute(os.Stdout, \"some text\")\n\tt1.Execute(os.Stdout, 5)\n\tt1.Execute(os.Stdout, []string{\n\t\t\"Go\",\n\t\t\"Rust\",\n\t\t\"C++\",\n\t\t\"C#\",\n\t})\n\n\t// Helper function we'll use below.\n\tCreate := func(name, t string) *template.Template {\n\t\treturn template.Must(template.New(name).Parse(t))\n\t}\n\n\t// If the data is a struct we can use the `{{.FieldName}}` action to access\n\t// its fields. The fields should be exported to be accessible when a"}]}],"commands":["go run text-templates.go"],"reference":[{"path":"text-templates.go","text":"// Go offers built-in support for creating dynamic content or showing customized\n// output to the user with the `text/template` package. A sibling package\n// named `html/template` provides the same API but has additional security\n// features and should be used for generating HTML.\n\npackage main\n\nimport (\n\t\"os\"\n\t\"text/template\"\n)\n\nfunc main() {\n    // TODO\n\t// We can create a new template and parse its body from\n\t// a string.\n\t// Templates are a mix of static text and \"actions\" enclosed in\n\t// `{{...}}` that are used to dynamically insert content.\n\t// Alternatively, we can use the `template.Must` function to\n\t// panic in case `Parse` returns an error. This is especially\n\t// useful for templates initialized in the global scope.\n\t// By \"executing\" the template we generate its text with\n\t// specific values for its actions. The `{{.}}` action is\n\t// replaced by the value passed as a parameter to `Execute`.\n\t// Helper function we'll use below.\n\t// If the data is a struct we can use the `{{.FieldName}}` action to access\n\t// its fields. The fields should be exported to be accessible when a\n\t// template is executing.\n\t// The same applies to maps; with maps there is no restriction on the\n\t// case of key names.\n\t// if/else provide conditional execution for templates. A value is considered\n\t// false if it's the default value of a type, such as 0, an empty string,\n\t// nil pointer, etc.\n\t// This sample demonstrates another\n\t// feature of templates: using `-` in actions to trim whitespace.\n\t// range blocks let us loop through slices, arrays, maps or channels. Inside\n\t// the range block `{{.}}` is set to the current item of the iteration.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"},"labex-go-go-time-and-duration-exploration":{"intro":"This lab aims to test your understanding of Go's time and duration support.","steps":[{"title":"Time","body":["The code below contains examples of how to work with time and duration in Go. However, some parts of the code are missing. Your task is to complete the code to make it work as expected.","• Basic knowledge of Go programming language. • Familiarity with Go's time and duration support."],"code":[{"lang":"sh","text":"$ go run time.go\n2012-10-31 15:50:13.793654 +0000 UTC\n2009-11-17 20:34:58.651387237 +0000 UTC\n2009\nNovember\n17\n20\n34\n58\n651387237\nUTC\nTuesday\ntrue\nfalse\nfalse\n25891h15m15.142266763s\n25891.25420618521\n1.5534752523711128e+06\n9.320851514226677e+07\n93208515142266763\n2012-10-31 15:50:13.793654 +0000 UTC\n2006-12-05 01:19:43.509120474 +0000 UTC\n\n# Next we'll look at the related idea of time relative to\n# the Unix epoch."},{"lang":"go","text":"// Go offers extensive support for times and durations;\n// here are some examples.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n\tp := fmt.Println\n\n\t// We'll start by getting the current time.\n\tnow := time.Now()\n\tp(now)\n\n\t// You can build a `time` struct by providing the\n\t// year, month, day, etc. Times are always associated\n\t// with a `Location`, i.e. time zone.\n\tthen := time.Date(\n\t\t2009, 11, 17, 20, 34, 58, 651387237, time.UTC)\n\tp(then)\n\n\t// You can extract the various components of the time\n\t// value as expected.\n\tp(then.Year())\n\tp(then.Month())\n\tp(then.Day())\n\tp(then.Hour())\n\tp(then.Minute())\n\tp(then.Second())\n\tp(then.Nanosecond())\n\tp(then.Location())\n\n\t// The Monday-Sunday `Weekday` is also available.\n\tp(then.Weekday())\n\n\t// These methods compare two times, testing if the\n\t// first occurs before, after, or at the same time\n\t// as the second, respectively.\n\tp(then.Before(now))\n\tp(then.After(now))\n\tp(then.Equal(now))\n\n\t// The `Sub` methods returns a `Duration` representing\n\t// the interval between two times.\n\tdiff := now.Sub(then)"}]}],"commands":["go run time.go"],"reference":[{"path":"time.go","text":"// Go offers extensive support for times and durations;\n// here are some examples.\n\npackage main\n\nimport (\n\t\"fmt\"\n\t\"time\"\n)\n\nfunc main() {\n    // TODO\n\t// We'll start by getting the current time.\n\t// You can build a `time` struct by providing the\n\t// year, month, day, etc. Times are always associated\n\t// with a `Location`, i.e. time zone.\n\t// You can extract the various components of the time\n\t// value as expected.\n\t// The Monday-Sunday `Weekday` is also available.\n\t// These methods compare two times, testing if the\n\t// first occurs before, after, or at the same time\n\t// as the second, respectively.\n\t// The `Sub` methods returns a `Duration` representing\n\t// the interval between two times.\n\t// We can compute the length of the duration in\n\t// various units.\n\t// You can use `Add` to advance a time by a given\n\t// duration, or with a `-` to move backwards by a\n\t// duration.\n}"}],"source":"mmcgrana/gobyexample · by jiaosenvip · CC-BY-3.0"}};
